INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eca4d132-5aea-529d-94c8-e2fac2127ca2','Wireless Multichannel Audio System (WMAS)','A wireless-audio architecture that carries many bidirectional audio channels inside a single wide radio-frequency block, typically several megahertz rather than the roughly 200 kHz occupied by one conventional narrowband transmitter. Instead of giving each microphone or in-ear monitor its own discrete carrier, a WMAS uses a shared wideband channel with multiplexing, commonly time-division duplex, so a base station and its bodypacks exchange audio, control, and monitoring data across the same allocation. Regulatory system-reference work permits these wider emissions, and a WMAS can trade audio latency, coding quality, and channel count against the fixed spectral resource. Capacity is often expressed as a number of usable channels per megahertz of occupied bandwidth.','A WMAS is a wireless microphone and monitor system. It uses one wide radio channel instead of many narrow ones. That single block can carry many audio channels at once. Signals can travel both to and from the bodypacks. Engineers trade sound quality, delay, and channel count for spectrum.','It concentrates large channel counts into a managed slice of spectrum, improving spectral efficiency and coordination for productions that need many wireless microphones and in-ear monitors at once. The shared wideband link also carries return telemetry and control, so one radio resource can serve talk and monitoring paths together.','A wireless coordinator deploys a WMAS base station on a large theatre, broadcast, or touring production, then allocates its channels among cast microphones and in-ear monitors while managing a single wideband block against local television spectrum and other users.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['Intermodulation coordination','In-ear monitor system','TV white space','Frequency coordination','Time-division duplex','Narrowband wireless microphone']::text[],ARRAY['Assuming a WMAS always fits more channels for free, when capacity still trades against latency and audio coding quality inside the fixed bandwidth','Treating the wideband block like a set of independent narrowband frequencies during intermodulation planning','Ignoring regional spectrum rules that govern the permitted occupied bandwidth and power for wideband operation']::text[],ARRAY['A musical with dozens of radio mics packs its channels into one coordinated wideband allocation','A broadcast facility uses bidirectional WMAS links to combine talent mics and monitor feeds on shared spectrum','A frequency coordinator compares narrowband and WMAS deployments for a congested urban radio environment']::text[],'intermediate','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wireless Multichannel Audio System (WMAS)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eca4d132-5aea-529d-94c8-e2fac2127ca2','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eca4d132-5aea-529d-94c8-e2fac2127ca2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eca4d132-5aea-529d-94c8-e2fac2127ca2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4027510f-7647-5e01-b0d9-9cbebc40aac8','Electric Network Frequency Analysis (ENF Analysis)','A forensic method that exploits small deviations of the electrical mains frequency from its nominal value, 50 Hz or 60 Hz, that arise as grid load and generation continuously rebalance. These fluctuations are near-identical across an interconnected grid at a given instant, so equipment powered from or exposed to the mains can imprint a matching frequency trace onto a recording through hum induction or power-supply coupling. Analysts extract the embedded frequency contour around the mains fundamental and its harmonics, then compare it against an independently logged reference of grid frequency to estimate recording time, confirm continuity, or reveal edits where the trace jumps, breaks, or fails to match. It is used chiefly for authentication and timestamping of questioned audio and video.','Mains power runs near 50 or 60 hertz. That exact rate drifts a little all the time. Recordings often pick up this hum from the power grid. Experts pull the hum''s changing pitch out of the audio. They match it to a log of real grid readings. This can show when a clip was made. It can also flag cuts or edits in the file.','It gives investigators an objective, grid-derived reference embedded in the recording itself, supporting decisions about when audio was captured, whether it plays continuously, and whether it has been spliced or otherwise altered.','A forensic audio examiner isolates the mains component with narrow filtering and frequency estimation, plots the extracted contour, and correlates it against a reference grid-frequency database to place or challenge a recording''s claimed time and integrity.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['Audio authentication','Mains hum','Spectrogram analysis','Chain of custody','Grid frequency reference','Tamper detection']::text[],ARRAY['Assuming every recording contains a usable frequency trace, when quiet mains, battery devices, or heavy processing can erase it','Confusing the 50 or 60 hertz hum component with musical or ambient energy at nearby frequencies','Reporting a match without a properly synchronised, same-grid reference log']::text[],ARRAY['Verifying the claimed recording date of an evidential phone call against a grid log','Detecting a hidden splice where the extracted mains contour breaks','Checking whether a video''s audio and images were captured together']::text[],'advanced','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electric Network Frequency Analysis (ENF Analysis)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4027510f-7647-5e01-b0d9-9cbebc40aac8','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4027510f-7647-5e01-b0d9-9cbebc40aac8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4027510f-7647-5e01-b0d9-9cbebc40aac8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9da28004-63c3-50be-834d-3806ed57f193','Forensic Speaker Comparison','The examination of a questioned, unknown speech recording against known reference speech to evaluate the strength of evidence for and against the proposition that they share a common speaker. Contemporary practice frames the result as a likelihood ratio: how much more probable the observed similarities and differences are if the samples came from the same speaker than from different speakers, given a relevant background population. Practitioners combine auditory-phonetic examination, acoustic measurement of features such as formants, fundamental frequency, and temporal patterns, and, increasingly, automatic speaker-recognition systems, while accounting for recording quality, channel mismatch, and within-speaker variation. Best-practice guidance stresses validated methods, calibrated systems, and avoidance of categorical identity claims.','This work compares two speech recordings. One voice is known. The other is in question. An expert weighs how alike and how different they sound. They measure things like pitch and vowel sounds. Software can also score the match. The result says how much the evidence favours a same-speaker view. Good practice avoids flat claims that it is surely one person.','It provides courts and investigators with a measured, defensible assessment of voice evidence, expressing support for competing same-speaker or different-speaker hypotheses instead of an absolute identification.','A forensic phonetician receives an intercepted call and a suspect''s reference recording, matches comparable speech material, measures acoustic features, runs a calibrated automatic system, and reports a likelihood ratio with its limitations.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['Likelihood ratio','Formant analysis','Automatic speaker recognition','Fundamental frequency','Voice biometrics','Channel mismatch']::text[],ARRAY['Stating a categorical same-person conclusion instead of an evidential likelihood ratio','Comparing mismatched material, such as different channels, styles, or languages, without accounting for its effect','Trusting an automatic score without validation, calibration, and a representative background population']::text[],ARRAY['Comparing a ransom call to a suspect interview recording','Assessing whether a threatening voicemail matches a known speaker','Evaluating disputed identity in a covert field recording']::text[],'advanced','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Forensic Speaker Comparison');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9da28004-63c3-50be-834d-3806ed57f193','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9da28004-63c3-50be-834d-3806ed57f193') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9da28004-63c3-50be-834d-3806ed57f193');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24410266-580e-512e-8830-ff5e28f59fbc','Cascaded Integrator-Comb Filter (CIC Filter)','A multiplier-free multirate digital filter, introduced by Hogenauer, built from a cascade of N integrator stages running at the high sample rate and N comb, or differencing, stages running at the low rate, separated by a rate change. Because each stage uses only additions, subtractions, and delays, the structure implements an efficient moving-average lowpass suited to very high decimation or interpolation ratios. Its magnitude response follows a raised sinc shape with nulls at multiples of the output rate, giving alias and image rejection, but also a gradual passband droop that is usually corrected by a following compensation FIR filter. Internal register growth from the integrators is handled with sufficient wordlength.','A CIC filter changes a signal''s sample rate cheaply. It uses only adds and delays, never multiplies. That makes it fast and simple in hardware. It stacks adder stages and subtractor stages together. It suits big rate changes, like thinning dense mic data. Its passband sags a little near the top. A second filter usually fixes that droop.','It performs the first, highest-ratio stage of sample-rate conversion with minimal hardware, providing anti-alias or anti-image lowpass filtering without costly multipliers in decimators and interpolators.','Designers place CIC stages in sigma-delta converters, PDM microphone decimation chains, and FPGA or ASIC radios to drop very high oversampled rates toward baseband, then add a short compensation FIR to flatten the passband.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['Decimation','Interpolation','Sigma-delta modulation','PDM microphone','Compensation FIR filter','Multirate signal processing']::text[],ARRAY['Forgetting the passband droop and omitting a compensation filter, which dulls high frequencies','Allocating too little internal wordlength, so integrator register growth overflows','Expecting sharp stopband selectivity from a CIC alone rather than cascading it with an FIR']::text[],ARRAY['Decimating a sigma-delta modulator''s bitstream to audio rates','Converting PDM MEMS-microphone output into PCM samples','Building an efficient down-converter in an FPGA software radio']::text[],'advanced','H(z) = [(1 - z^-RM) / (1 - z^-1)]^N','The transfer function is the quantity one minus z raised to the power negative R times M, divided by one minus z raised to the power negative one, with the whole ratio raised to the power N, where R is the rate-change ratio, M is the differential delay, and N is the number of integrator-comb stages.','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cascaded Integrator-Comb Filter (CIC Filter)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24410266-580e-512e-8830-ff5e28f59fbc','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24410266-580e-512e-8830-ff5e28f59fbc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24410266-580e-512e-8830-ff5e28f59fbc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ba2f6498-c9b2-5c6f-abbc-47551dcf1f3d','NMOS IS-08 Audio Channel Mapping','An AMWA Networked Media Open Specifications interface that standardises how audio channels are mapped between a device''s inputs and outputs over an IP network. Through its Channel Mapping API, a controller can query a device''s inputs, outputs, and routing constraints, then set a map that assigns individual input channels to output channels, with immediate or scheduled activation. Inputs may originate from network receivers or physical ports, and outputs may feed network sources or local destinations, so the specification governs the internal channel routing that sits behind stream connection. It complements the discovery and connection-management interfaces of the same family and is commonly used with ST 2110-30 or AES67 audio flows.','IS-08 controls how audio channels move inside a network device. It maps input channels onto output channels. A controller reads what a device can route. Then it sets the wanted channel layout. Changes can happen now or at a set time. It works with other tools that find and connect streams.','It gives broadcast control systems a uniform, vendor-neutral way to reshuffle audio channels within devices, so operators can build the exact channel order a downstream stream or output needs.','An IP-facility controller uses the Channel Mapping API to reorder embedded audio, split or combine channels on a gateway, or set a receiver''s channel layout before an ST 2110-30 flow reaches a mixer.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['NMOS IS-04','NMOS IS-05','SMPTE ST 2110-30','AES67','Audio channel routing','Broadcast controller']::text[],ARRAY['Confusing internal channel mapping with the interface that manages the stream connections themselves','Assuming any input channel can reach any output, ignoring the device''s declared routing constraints','Overlooking scheduled activation and expecting every map change to apply instantly']::text[],ARRAY['Reordering embedded audio channels on an IP gateway before distribution','Setting a receiver''s channel map ahead of a live program','Combining discrete mic channels into a grouped output on a networked device']::text[],'intermediate','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='NMOS IS-08 Audio Channel Mapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ba2f6498-c9b2-5c6f-abbc-47551dcf1f3d','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ba2f6498-c9b2-5c6f-abbc-47551dcf1f3d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ba2f6498-c9b2-5c6f-abbc-47551dcf1f3d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1c281d0-8ce3-596e-a8d1-f301bbf3f710','SMPTE ST 2110-30 - PCM Digital Audio','The audio element of the SMPTE ST 2110 suite, specifying carriage of uncompressed linear PCM audio as discrete essence over managed IP networks using RTP. It is built directly on AES67, constraining sampling to professional rates, defining channel counts and packet times, including short packet intervals for low latency, and grouping these into conformance levels so interoperable senders and receivers can be matched. Audio, video, and ancillary data travel as separate synchronised streams timed to a shared precision-time reference, letting audio be routed and processed independently. Because it aligns with AES67, ST 2110-30 audio can interwork with compliant audio-over-IP devices.','ST 2110-30 sends studio audio over an IP network. The audio stays uncompressed PCM. It rides in RTP packets, like other network media. It builds on the AES67 audio standard. Video and audio travel as separate timed streams. A shared clock keeps everything in sync. Set packet sizes trade latency against network load.','It lets facilities move high-quality audio as an independent networked essence, decoupled from video, so audio can be switched, mixed, and monitored on standard IP infrastructure with predictable timing.','A broadcast engineer configures ST 2110-30 senders and receivers with matching sample rate, channel count, and packet time, verifies precision-time lock, and routes audio flows across a spine-leaf network into consoles and processors.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['AES67','SMPTE ST 2110-10','Precision Time Protocol','RTP','SMPTE ST 2110-31','SMPTE ST 2059']::text[],ARRAY['Mismatching packet time or channel count between sender and receiver, so streams fail to interoperate','Assuming ST 2110-30 carries compressed or non-PCM audio, which belongs to the transparent AES3 mapping','Neglecting network timing, which breaks synchronisation between separate audio and video flows']::text[],ARRAY['Routing console audio across an IP broadcast core','Interworking ST 2110-30 audio with an AES67 domain through a gateway','Setting low packet times for a live production that needs minimal audio latency']::text[],'intermediate','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SMPTE ST 2110-30 - PCM Digital Audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1c281d0-8ce3-596e-a8d1-f301bbf3f710','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1c281d0-8ce3-596e-a8d1-f301bbf3f710') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1c281d0-8ce3-596e-a8d1-f301bbf3f710');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee2531be-6790-56d3-a8c8-28efe9369ff9','SMPTE ST 2110-31 - AES3 Transparent Transport','A SMPTE ST 2110 mapping that transports complete AES3 digital-audio streams transparently over IP using RTP, carrying the AES3 subframe payload rather than only decoded PCM. By preserving the full AES3 data, it conveys non-PCM and encoded content, such as Dolby E and other bitstreams, together with channel-status and associated metadata that a pure PCM mapping would discard. Like the rest of the suite it runs as a separate, precision-time-synchronised essence and shares AES67-derived transport conventions, so facilities can move legacy AES3 payloads and metadata across the same IP fabric used for uncompressed audio and video. It is chosen wherever the exact AES3 bitstream must survive end to end.','ST 2110-31 carries AES3 audio across an IP network. It keeps the whole AES3 data intact. So it can pass coded audio, not just plain PCM. Formats like Dolby E survive the trip. It also keeps the channel-status metadata. It runs as its own timed stream, like the video.','It preserves complete AES3 signals, including encoded audio and embedded metadata, across IP, so bitstreams and status bits reach their destination unchanged instead of being lost by a PCM-only path.','An engineer uses ST 2110-31 to route Dolby E or other AES3 bitstreams and their metadata through an IP plant, feeding decoders or downstream devices that need the original AES3 payload.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['AES3','SMPTE ST 2110-30','Dolby E','Channel status','AES67','Non-PCM audio']::text[],ARRAY['Assuming the PCM mapping can carry Dolby E or other bitstreams, when transparent AES3 needs the -31 mapping','Forgetting that AES3 channel-status and metadata must be preserved, not stripped','Mismatching AES3 payload framing between endpoints so encoded audio fails to decode']::text[],ARRAY['Passing a Dolby E stream through an IP facility to a downstream decoder','Carrying AES3 metadata alongside audio across a networked plant','Bridging legacy AES3 sources into an ST 2110 environment']::text[],'intermediate','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SMPTE ST 2110-31 - AES3 Transparent Transport');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee2531be-6790-56d3-a8c8-28efe9369ff9','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee2531be-6790-56d3-a8c8-28efe9369ff9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee2531be-6790-56d3-a8c8-28efe9369ff9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd14aae42-7762-5e0e-9f1c-2d00f2110548','AES70 / Open Control Architecture (OCA)','An AES standard, developed from the Open Control Architecture, that defines a scalable framework for controlling and monitoring professional audio and media devices over IP networks. It specifies an object-oriented device model in which functions are represented as standardised control objects, a protocol for exchanging commands, responses, and event notifications, and mechanisms for discovery and connection management. The standard addresses control and monitoring only, such as setting parameters, reading meters, and subscribing to state changes, rather than transporting audio, so it is deliberately transport-agnostic and typically pairs with media standards such as AES67 or ST 2110. Its structured model lets multi-vendor systems be managed through a common interface.','AES70 is a control system for audio gear on a network. It does not carry the audio itself. Instead it sets and reads device settings. Each function appears as a standard control object. Software can change gains, read meters, and watch for changes. It works next to audio streams like AES67. So one app can manage gear from many brands.','It provides a common, vendor-neutral control and monitoring layer, letting controllers configure parameters, read status, and receive event updates from many devices without proprietary protocols, alongside separate audio transport.','A system integrator uses an AES70 controller to set amplifier gains, mute states, and monitor fault or level data across networked amplifiers and processors, while AES67 or ST 2110 handles the audio itself.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['Open Control Architecture','AES67','Device control protocol','OCP.1','Network monitoring','SMPTE ST 2110']::text[],ARRAY['Believing AES70 transports audio, when it only handles control and monitoring','Expecting control to work without a separate, correctly configured audio transport','Assuming all devices expose identical objects, ignoring vendor-specific extensions to the model']::text[],ARRAY['Remotely adjusting amplifier gains across an installed venue','Monitoring device faults and levels from a central controller','Managing a multi-vendor networked audio system through one control interface']::text[],'intermediate','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='AES70 / Open Control Architecture (OCA)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd14aae42-7762-5e0e-9f1c-2d00f2110548','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d14aae42-7762-5e0e-9f1c-2d00f2110548') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d14aae42-7762-5e0e-9f1c-2d00f2110548');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7ec2a2f-ee74-5e31-91ad-9c82886ffe7e','Music-Noise Test Signal','A standardised test signal, defined within the AES75 loudspeaker-measurement standard, whose spectrum and high, frequency-dependent crest factor emulate the statistics of real music program material. Derived from analysis of a large body of musical recordings, it couples defined RMS and peak levels as functions of frequency so that it stresses a loudspeaker much as music does, unlike steady tones or conventional flat-crest noise. In the measurement procedure the signal level is raised in steps until the loudspeaker''s acoustic output deviates from linear behaviour, judged by an agreed change in magnitude or coherence, establishing the maximum linear sound level as a repeatable, manufacturer-independent specification.','This is a special test sound for loudspeakers. Its shape and peaks act like real music. Plain tones do not stress a speaker the same way. Engineers play it and slowly raise the level. They watch when the speaker''s output stops tracking cleanly. That point sets the speaker''s top clean loudness. This gives a fair number to compare brands.','It supplies a music-like excitation so that a loudspeaker''s maximum linear sound level is measured under realistic dynamics, yielding a consistent, comparable rating rather than one inflated by unrealistic test signals.','A loudspeaker engineer plays the signal into a system, raises level in steps while tracking magnitude and coherence, and records the highest level at which output stays linear as the published maximum linear sound level.','Wireless, Forensic, DSP, Networking & Standards',ARRAY['Maximum linear sound level','Crest factor','Pink noise','Coherence measurement','Loudspeaker specification','Program material']::text[],ARRAY['UNSAFE: running the test at maximum drive without hearing protection or a safe exclusion zone around the loudspeaker','Comparing this music-like rating with a peak sound-level figure from a different, unrelated test method','Assuming a simple sine or pink-noise level predicts the music-like maximum linear result']::text[],ARRAY['Rating a touring loudspeaker''s maximum linear sound level for a spec sheet','Comparing two systems fairly under a common music-like signal','Validating that a speaker meets its published level under realistic dynamics']::text[],'intermediate','','','f851bfc8-f928-46ff-912c-826a7e7c675c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Music-Noise Test Signal');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7ec2a2f-ee74-5e31-91ad-9c82886ffe7e','f851bfc8-f928-46ff-912c-826a7e7c675c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7ec2a2f-ee74-5e31-91ad-9c82886ffe7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7ec2a2f-ee74-5e31-91ad-9c82886ffe7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ecac2825-1c00-5cf4-8aad-54ae7e3eb143','Audio Definition Model (ADM)','A standardised XML metadata model that describes the format and content of audio programmes independently of the audio essence itself. It defines a hierarchy of elements distinguishing content (what the audio represents, such as a programme, object, or bed) from format (how the audio samples are structured), and supports channel-based, object-based, and scene-based (Ambisonic/HOA) representations. Elements such as audioProgramme, audioObject, audioPackFormat, audioChannelFormat, and audioTrackUID reference one another to describe positions, gains, importance, and rendering intent, allowing a renderer to reproduce the intended presentation across differing loudspeaker layouts and headphones.','The Audio Definition Model is a set of labels for audio. It tells a system what each sound is. It can mark fixed channels, moving objects, or a full sound scene. A player reads these labels. Then it knows how to play the sound in a room. So one file can suit many speaker setups.','It provides a common, technology-neutral way to describe next-generation and immersive audio so that content and its rendering intent survive exchange between tools, facilities, and delivery systems. By separating descriptive metadata from the samples, it lets a single set of audio tracks be interpreted and rendered correctly for any reproduction layout.','A technician meets ADM when exporting immersive mixes from a DAW or authoring tool, embedding it as axml metadata inside a BW64 file, or feeding it to a renderer for monitoring. It underpins production workflows for MPEG-H, AC-4, and DTS:X and file exchange between broadcasters.','Immersive Audio, Metadata & File Formats',ARRAY['audioTrackUID','Serial Audio Definition Model (S-ADM)','BW64','ADM Renderer','object-based audio','audioPackFormat']::text[],ARRAY['Assuming ADM is an audio codec or file format rather than a metadata model that only describes audio','Confusing ADM content elements with format elements, which breaks the reference chain a renderer needs','Believing ADM is limited to object-based audio when it also covers channel-based and scene-based content']::text[],ARRAY['Exporting an immersive music mix with object metadata for delivery to a streaming platform','Exchanging a broadcast programme as a BW64 file whose ADM describes every track','Authoring a bed-plus-objects mix that must render to both 7.1.4 and stereo']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio Definition Model (ADM)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ecac2825-1c00-5cf4-8aad-54ae7e3eb143','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ecac2825-1c00-5cf4-8aad-54ae7e3eb143') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ecac2825-1c00-5cf4-8aad-54ae7e3eb143');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce5b4cdd-d6d2-55ea-8509-658afa6cfbff','Serial Audio Definition Model (S-ADM)','A time-segmented serialisation of the Audio Definition Model that partitions ADM metadata into successive frames aligned with blocks of audio samples, making the model suitable for live production, contribution, and streaming. Each frame carries a frameHeader defining timing, duration, frame type, and flow identification, plus an audioFormatExtended payload. Frame types (such as header, full, intermediate, divided, and all) and flow patterns trade metadata repetition against random-access capability. The recommendation defines the serial structure but deliberately leaves the choice of transport interface open.','Serial ADM is a live version of the audio labels. It splits the labels into small time slices called frames. Each frame lines up with a piece of audio. This lets the labels flow in real time. Live TV and streaming use it. Plain ADM only works for finished files, not live feeds.','It exists because file-based ADM is a single monolithic document that cannot describe audio arriving continuously in real time. Serialising the model into frames lets immersive and object metadata travel synchronously with the audio through broadcast chains, updating object positions and properties as they change.','Engineers encounter S-ADM when carrying next-generation audio metadata over AES3, MADI, SDI, or IP interfaces during live sports and events, or when it is embedded as an sxml chunk in a BW64 file. It commonly rides alongside emission codecs such as AC-4.','Immersive Audio, Metadata & File Formats',ARRAY['Audio Definition Model (ADM)','SXML Chunk','Metadata-Guided Audio (MGA)','SMPTE ST 2127-2','frame header','object-based audio']::text[],ARRAY['Treating S-ADM as a different metadata model rather than a time-framed serialisation of the same ADM','Assuming the recommendation defines a transport, when it intentionally leaves carriage to interface specifications','Ignoring frame-type choice, so intermediate-only flows are used where random access is required']::text[],ARRAY['Delivering object-based commentary and effects metadata during a live sports broadcast','Carrying immersive metadata frame-by-frame across a facility over MADI','Feeding a live encoder that maps S-ADM into an emission bitstream']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Serial Audio Definition Model (S-ADM)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce5b4cdd-d6d2-55ea-8509-658afa6cfbff','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce5b4cdd-d6d2-55ea-8509-658afa6cfbff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce5b4cdd-d6d2-55ea-8509-658afa6cfbff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bcb86e5d-686e-53e7-a6fd-6a20a15d65b2','BW64','A professional multichannel audio file format, the successor to RF64, that extends the RIFF/WAVE structure to support files larger than four gigabytes and to carry Audio Definition Model metadata. The first four bytes read ''BW64'' instead of ''RIFF'', and a mandatory ds64 chunk supplies 64-bit size values that override the 32-bit RIFF and data fields when those are set to 0xFFFFFFFF. It adds ADM-related chunks including chna for track-to-metadata references and axml, bxml, or sxml for the XML metadata itself.','BW64 is a pro audio file type. It works like a WAV file but can be much bigger. Normal WAV files stop at four gigabytes. BW64 can go past that limit. It can also hold audio labels inside the file. Long recordings with many channels use it.','It overcomes the 4 GB ceiling of 32-bit RIFF/WAVE addressing that limits long or high-channel-count recordings, while adding a home for immersive audio metadata. This lets a single self-contained file carry both the audio tracks and the ADM description needed to render them.','Technicians produce and read BW64 files when mastering or exchanging immersive and multichannel content, since DAWs and renderers write ADM into these files. The format is the standard container for delivering ADM-described programmes between production tools and broadcasters.','Immersive Audio, Metadata & File Formats',ARRAY['RF64','CHNA Chunk','BXML Chunk','SXML Chunk','Audio Definition Model (ADM)','ds64 chunk']::text[],ARRAY['Assuming any standard WAV reader can open BW64, when the differing four-character identifier requires 64-bit support','Overlooking the ds64 chunk, so oversized files are mis-parsed as 4 GB or truncated','Confusing BW64 the container with ADM the metadata it may carry']::text[],ARRAY['Mastering a feature-length immersive mix that exceeds four gigabytes as one file','Delivering a multichannel programme with embedded ADM to a broadcaster','Archiving a high-track-count session as a self-describing audio file']::text[],'intermediate','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BW64');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bcb86e5d-686e-53e7-a6fd-6a20a15d65b2','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bcb86e5d-686e-53e7-a6fd-6a20a15d65b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bcb86e5d-686e-53e7-a6fd-6a20a15d65b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eae8117e-2e17-5890-befb-ad338c9bc22b','CHNA Chunk','A channel-allocation chunk within a BW64 file that maps each physical audio track in the file to the corresponding identifiers in the Audio Definition Model. Each entry pairs a track index with an audioTrackUID and references to the relevant audioTrackFormat or audioChannelFormat and audioPackFormat elements defined in the ADM. It provides a compact, fast index so that a reader can associate interleaved audio channels with their descriptive metadata without parsing the full XML.','The chna chunk is a small table inside a BW64 file. It links each audio track to its label. Think of it as a seating chart. It says which track holds which sound. Without it, a player cannot match tracks to their labels.','It bridges the raw audio tracks and the ADM description, telling a renderer or reader which channel in the file corresponds to which ADM element. This lookup makes it possible to route and render each track correctly even before the full metadata is processed.','Engineers rely on the chna chunk whenever a BW64 file is opened in a renderer or validation tool, since a wrong or missing entry causes channels to be misrouted. It is checked during quality control of immersive deliverables.','Immersive Audio, Metadata & File Formats',ARRAY['BW64','audioTrackUID','Audio Definition Model (ADM)','audioPackFormat','axml chunk','audioTrackFormat']::text[],ARRAY['Assuming the chna chunk stores the full ADM, when it only holds track-to-ID references','Leaving stale entries after re-ordering tracks, which misassigns channels to metadata','Confusing the track index in chna with the ADM audioTrackUID string it points to']::text[],ARRAY['Validating that every track in a delivered BW64 file maps to a valid ADM element','Troubleshooting a renderer that places a channel in the wrong position','Building a BW64 writer that must populate track references correctly']::text[],'intermediate','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='CHNA Chunk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eae8117e-2e17-5890-befb-ad338c9bc22b','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eae8117e-2e17-5890-befb-ad338c9bc22b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eae8117e-2e17-5890-befb-ad338c9bc22b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '484b692f-0547-59eb-b306-daff81feb295','BXML Chunk','A BW64 chunk that carries compressed XML metadata in place of the uncompressed axml chunk. It holds the same class of XML data, typically Audio Definition Model metadata, but stored using gzip compression as defined by the relevant IETF specification, with a format-type field indicating the compression method. It reduces the storage footprint of large metadata payloads while remaining functionally equivalent to axml once decompressed.','The bxml chunk holds audio labels inside a file. The labels are written in XML text. This chunk squeezes that text smaller using zip. It saves space when the label data is large. It does the same job as the plain axml chunk.','It exists to keep metadata size manageable when ADM descriptions grow large, since verbose XML can occupy significant space. Compressing the payload lets a file carry rich, detailed metadata without inflating the overall file size.','A technician encounters bxml when working with immersive files whose ADM metadata is extensive, where tools may write the compressed form to save space. Readers must decompress it to recover the same information the axml chunk would provide.','Immersive Audio, Metadata & File Formats',ARRAY['BW64','axml chunk','SXML Chunk','Audio Definition Model (ADM)','gzip compression','CHNA Chunk']::text[],ARRAY['Expecting to read bxml as plain text, when it must first be decompressed','Assuming bxml and axml can both be present and identical, when bxml substitutes for axml','Overlooking the format-type field that signals which compression method was used']::text[],ARRAY['Storing an unusually large ADM description compactly inside a BW64 deliverable','Parsing a file whose metadata was written in compressed form','Choosing between axml and bxml when authoring an immersive master']::text[],'intermediate','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='BXML Chunk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '484b692f-0547-59eb-b306-daff81feb295','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='484b692f-0547-59eb-b306-daff81feb295') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='484b692f-0547-59eb-b306-daff81feb295');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b4b1326-6a1c-54e4-a4e9-eb875ce831f0','SXML Chunk','A BW64 chunk that carries serial Audio Definition Model metadata, associating time-segmented frames of ADM information with corresponding segments of audio data within the file. It may hold compressed or uncompressed XML and is specifically intended for the serial representation defined in the S-ADM recommendation, allowing metadata that varies over time to be stored alongside the audio essence rather than as a single static document.','The sxml chunk holds live-style audio labels inside a file. These labels come in time-based frames. It stores the serial form of ADM. This lets labels change over time with the audio. Content whose sound moves over time uses it.','It provides a place inside a BW64 file for time-variant, frame-based S-ADM metadata, which the static axml and bxml chunks are not designed to hold. This supports content whose object positions or properties evolve across the timeline.','Engineers meet the sxml chunk when a BW64 file must preserve serial ADM captured from a live or dynamic workflow, so that time-changing object metadata is retained on disk. It links frames of metadata to matching audio segments.','Immersive Audio, Metadata & File Formats',ARRAY['BW64','Serial Audio Definition Model (S-ADM)','BXML Chunk','axml chunk','Audio Definition Model (ADM)','frame header']::text[],ARRAY['Confusing sxml, which holds time-framed serial ADM, with axml, which holds a single static ADM document','Assuming sxml is always uncompressed, when it may hold compressed or uncompressed XML','Expecting a static-ADM reader to interpret the time alignment sxml provides']::text[],ARRAY['Storing captured S-ADM frames from a live immersive feed as a file','Preserving evolving object positions across a programme timeline on disk','Round-tripping serial metadata between a recorder and a renderer']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SXML Chunk');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b4b1326-6a1c-54e4-a4e9-eb875ce831f0','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b4b1326-6a1c-54e4-a4e9-eb875ce831f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b4b1326-6a1c-54e4-a4e9-eb875ce831f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e665e506-777c-51f0-9191-b18d436f72e0','Metadata-Guided Audio (MGA)','A framework in which audio essence is accompanied by descriptive metadata, principally serial Audio Definition Model data, that guides how compatible systems route, process, and render the audio. Standardised in the SMPTE ST 2127 family, it defines how next-generation and immersive audio programmes are packaged so that the sound and its rendering instructions stay bound together as they move through production and distribution. Companion standards specify its storage in MXF and its transport over professional IP infrastructure.','Metadata-Guided Audio pairs sound with a set of labels. The labels tell a system how to play the sound. This supports 3D and object-based audio. It moves audio through TV gear as one unit. Set rules say how to store it and send it.','It exists to keep immersive audio and its rendering metadata together as a single managed entity throughout professional workflows, rather than letting the two drift apart. This ensures that the intended presentation can be reconstructed reliably at any downstream point.','Broadcast engineers meet MGA when handling next-generation audio in file-based and live IP facilities, where it is stored in MXF and streamed over ST 2110 infrastructure. It carries the S-ADM metadata that emission encoders ultimately consume.','Immersive Audio, Metadata & File Formats',ARRAY['Serial Audio Definition Model (S-ADM)','SMPTE ST 2127-1','SMPTE ST 2127-2','Audio Definition Model (ADM)','MXF','object-based audio']::text[],ARRAY['Treating MGA as a codec, when it is a framework binding audio essence to guiding metadata','Assuming MGA metadata is optional decoration rather than instructions that shape rendering','Confusing the MGA storage standard for MXF with the separate standard for IP transport']::text[],ARRAY['Packaging an immersive programme so its audio and metadata travel together through a plant','Feeding MGA into an encoder that produces a next-generation emission stream','Exchanging metadata-rich audio between facilities in a standardised container']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Metadata-Guided Audio (MGA)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e665e506-777c-51f0-9191-b18d436f72e0','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e665e506-777c-51f0-9191-b18d436f72e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e665e506-777c-51f0-9191-b18d436f72e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '78e19e96-3eac-55a6-9fb3-76a6cd92ff40','SMPTE ST 2127-1','A SMPTE standard that specifies how Metadata-Guided Audio signals are mapped into the MXF Constrained Generic Container. It defines the file-based packaging that keeps audio essence and its accompanying S-ADM metadata together within an MXF wrapper, establishing the labels, structure, and constraints needed for interoperable storage and exchange of next-generation audio in professional file workflows.','SMPTE ST 2127-1 is a storage rule. It says how to put Metadata-Guided Audio into an MXF file. MXF is a common media wrapper for TV. The rule keeps the audio and its labels together. This helps files work across different tools.','It provides a standardised, interoperable way to store immersive audio and its guiding metadata in MXF, the container widely used across professional media. By fixing the mapping, it lets different vendors write and read the same files reliably.','Engineers rely on ST 2127-1 when creating or ingesting MXF files that hold next-generation audio, ensuring the metadata survives file exchange between facilities and tools. It is referenced in delivery specifications for immersive programmes.','Immersive Audio, Metadata & File Formats',ARRAY['Metadata-Guided Audio (MGA)','SMPTE ST 2127-2','MXF','Serial Audio Definition Model (S-ADM)','Constrained Generic Container','SMPTE ST 2067-204']::text[],ARRAY['Confusing ST 2127-1, which covers MXF file storage, with ST 2127-2, which covers IP transport','Assuming any MXF audio track carries MGA, when the specific mapping must be followed','Overlooking the Constrained Generic Container requirement when authoring the file']::text[],ARRAY['Wrapping an immersive audio programme into an MXF file for archive and exchange','Verifying that a delivered MXF conforms to the MGA mapping','Interchanging metadata-rich audio between post-production systems']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SMPTE ST 2127-1');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '78e19e96-3eac-55a6-9fb3-76a6cd92ff40','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='78e19e96-3eac-55a6-9fb3-76a6cd92ff40') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='78e19e96-3eac-55a6-9fb3-76a6cd92ff40');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f0631713-9d09-5176-87ff-2e9b3dd8741a','SMPTE ST 2127-2','A SMPTE standard that specifies how Metadata-Guided Audio metadata is carried within the fast-metadata framework of ST 2110-41 for real-time IP transport. It defines the mapping of MGA payloads into time-synchronised metadata packets, so that the guiding S-ADM metadata travels alongside audio essence delivered on an ST 2110-30 stream, keeping description and audio aligned across a professional IP network.','SMPTE ST 2127-2 is a transport rule. It says how to send Metadata-Guided Audio over a network. It uses a fast metadata stream called ST 2110-41. The labels travel in time with the audio. This suits live IP-based TV plants.','It exists to move immersive audio metadata across live IP infrastructure in time with the audio, complementing the file-based storage defined by its companion standard. This lets the guiding metadata stay synchronised with the essence during real-time production and contribution.','Engineers use ST 2127-2 in ST 2110 IP facilities where next-generation audio is routed as separate essence and metadata flows. The audio rides an ST 2110-30 stream while the aligned metadata rides the fast-metadata stream.','Immersive Audio, Metadata & File Formats',ARRAY['Metadata-Guided Audio (MGA)','SMPTE ST 2127-1','SMPTE ST 2110-41','Serial Audio Definition Model (S-ADM)','SMPTE ST 2110-30','fast metadata']::text[],ARRAY['Confusing ST 2127-2, which handles IP transport, with ST 2127-1, which handles MXF storage','Assuming the audio and metadata share one stream, when essence and metadata are separate aligned flows','Neglecting the timing model, which breaks synchronisation between metadata and audio']::text[],ARRAY['Routing immersive audio and its metadata as synchronised flows in an IP broadcast plant','Contributing next-generation audio over a professional network to a central facility','Feeding a live encoder from separate ST 2110 audio and metadata streams']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SMPTE ST 2127-2');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f0631713-9d09-5176-87ff-2e9b3dd8741a','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f0631713-9d09-5176-87ff-2e9b3dd8741a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f0631713-9d09-5176-87ff-2e9b3dd8741a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c428cda-a4ff-5709-95f0-561d026831a1','SMPTE ST 2067-204','A SMPTE standard within the Interoperable Master Format family that defines a plug-in for carrying audio accompanied by Audio Definition Model metadata, including its serial representation, inside IMF packages. It specifies how ADM-described immersive and object-based audio essence and metadata are packaged as IMF-conformant assets, extending the master format so that metadata-rich next-generation audio can be exchanged and versioned within interoperable master packages.','SMPTE ST 2067-204 is a rule for master file packages. These packages are called IMF. The rule lets them carry audio with ADM labels. This includes the live serial form of ADM. It helps studios move rich audio between systems.','It fills a gap in the IMF ecosystem by letting master packages carry immersive audio with full ADM description, not just basic audio tracks. This supports metadata-rich audio delivery and versioning within the standardised master format used across streaming and post.','Technicians encounter ST 2067-204 when building or ingesting IMF packages that must retain ADM-based immersive audio for distribution masters. It lets object and serial ADM metadata accompany the audio through interoperable master workflows.','Immersive Audio, Metadata & File Formats',ARRAY['Interoperable Master Format','Audio Definition Model (ADM)','Serial Audio Definition Model (S-ADM)','Metadata-Guided Audio (MGA)','SMPTE ST 2067-2','MXF']::text[],ARRAY['Assuming standard IMF audio already carries ADM, when the plug-in must be applied','Confusing the IMF ADM plug-in with the separate MGA-over-MXF and MGA-over-IP standards','Overlooking that it supports serial as well as file-based ADM metadata']::text[],ARRAY['Assembling an IMF distribution master that retains object-based audio metadata','Delivering an immersive title to a platform that ingests IMF packages','Versioning a master while preserving its ADM audio description']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SMPTE ST 2067-204');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c428cda-a4ff-5709-95f0-561d026831a1','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c428cda-a4ff-5709-95f0-561d026831a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c428cda-a4ff-5709-95f0-561d026831a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f247e27-d294-57c2-a9b5-753b2ff94b20','ADM Renderer','A processor that interprets Audio Definition Model metadata together with its associated audio and produces a specific reproduction, such as feeds for a defined loudspeaker layout or a binaural headphone signal. The reference renderer standardised by the ITU provides a complete interpretation of ADM, handling channel-based, object-based, and scene-based content and applying the described positions, gains, and importance so that a mix can be monitored the same way an audience will hear it across different systems.','An ADM renderer is a piece of software. It reads the audio and its labels. Then it turns them into real speaker feeds. It can also make headphone sound. This lets everyone hear the mix the same way. It works for many speaker layouts from one file.','It exists to convert the abstract, layout-independent ADM description into concrete signals for an actual reproduction setup, giving a consistent, standardised reference. This lets producers monitor immersive content reliably and lets any layout be served from one metadata-described master.','Engineers use an ADM renderer to monitor immersive mixes during production, to audition how a programme collapses to smaller layouts, and to validate delivered BW64 or IMF files. The ITU reference implementation is available as open-source software.','Immersive Audio, Metadata & File Formats',ARRAY['Audio Definition Model (ADM)','BW64','Serial Audio Definition Model (S-ADM)','binaural rendering','object-based audio','loudspeaker layout']::text[],ARRAY['Expecting different renderers to sound identical when they diverge from the reference algorithm','Assuming the renderer stores audio, when it only interprets metadata and audio to produce output','Believing it handles only object-based audio, when it also renders channel and scene-based content']::text[],ARRAY['Monitoring an object-based mix on a 7.1.4 layout during mastering','Auditioning a binaural fold-down of an immersive programme for headphones','Validating a delivered ADM file against the reference reproduction']::text[],'advanced','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='ADM Renderer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f247e27-d294-57c2-a9b5-753b2ff94b20','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f247e27-d294-57c2-a9b5-753b2ff94b20') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f247e27-d294-57c2-a9b5-753b2ff94b20');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9fed70e-91b4-5d7c-92f0-6a7c315dbb35','audioTrackUID','An Audio Definition Model element that uniquely identifies a single audio track or asset within a file or recording and links it to the descriptive metadata that applies to it. Written in the form ATU_ followed by a hexadecimal value, it references the relevant audioTrackFormat and audioPackFormat, and may carry sample-rate and bit-depth attributes. In BW64 files it is the identifier the chna chunk uses to bind a physical track to the ADM, and it can perform that binding directly for non-BW64 applications.','An audioTrackUID is a unique name for one audio track. It acts like a name tag. It links a track to its matching labels. Each track gets its own tag. This lets a system find the right label for each sound.','It provides the anchor point that connects raw audio tracks to the ADM structures describing them, ensuring every track can be traced to its format and pack description. Without such a unique reference, a renderer could not reliably match audio to metadata.','Technicians see audioTrackUID values in chna entries and ADM XML when authoring or debugging immersive files. A duplicated or dangling identifier is a common cause of tracks failing to render or being routed incorrectly.','Immersive Audio, Metadata & File Formats',ARRAY['Audio Definition Model (ADM)','CHNA Chunk','audioTrackFormat','audioPackFormat','BW64','audioChannelFormat']::text[],ARRAY['Reusing the same audioTrackUID for more than one track, which corrupts the metadata mapping','Confusing audioTrackUID, an instance identifier, with the shared format IDs it references','Leaving a reference pointing to a format element that does not exist in the metadata']::text[],ARRAY['Tracing why one channel of an immersive file fails to render correctly','Assigning unique identifiers to every track when authoring an ADM file','Auditing a delivered BW64 file for duplicate or dangling track references']::text[],'intermediate','','','9573ac8c-5821-4749-8bfd-d3b39cf3657c' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='audioTrackUID');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9fed70e-91b4-5d7c-92f0-6a7c315dbb35','9573ac8c-5821-4749-8bfd-d3b39cf3657c',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9fed70e-91b4-5d7c-92f0-6a7c315dbb35') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9fed70e-91b4-5d7c-92f0-6a7c315dbb35');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b2f8fbba-7c4e-5ef8-b690-520f3f0c9cf8','Automotive Audio Bus (A2B)','A2B is a digital automotive networking technology that transports multiple channels of synchronous audio, control data, a common bit clock, and DC power over a single unshielded twisted-pair line arranged as a daisy-chained line topology. A main transceiver acts as clock master; subordinate nodes downstream recover clock and data and exchange time-division-multiplexed audio slots, supporting on the order of dozens of upstream and downstream channels at typical automotive sample rates. Nodes may draw operating power from the bus itself, and an embedded control channel tunnels register access between the host and remote devices.','A2B is a small automotive network. It sends many audio channels down one twisted-pair wire. The same wire also carries control data, a clock, and power. This cuts cable weight and cost in cars.','It reduces the harness weight, connector count, and cost of distributing digital audio to distributed microphones, amplifiers, and speaker modules by collapsing audio, clock, control, and power onto one low-cost twisted pair with deterministic, low latency across all nodes.','Engineers use A2B to link roof and pillar microphone arrays, remote amplifiers, and satellite speakers for hands-free calling, active noise control reference pickups, and zoned playback; integration involves I2S/TDM framing to a host processor and I2C-style register configuration of each node.','Automotive Audio Systems',ARRAY['Media Oriented Systems Transport (MOST)','Time-division multiplexing','I2S audio interface','Automotive Ethernet','In-Car Communication (ICC)']::text[],ARRAY['Assuming A2B is a full multimedia network like MOST or Ethernet rather than a deterministic point-to-point audio and control link','Forgetting that total bus-powered current is limited, so high-power amplifier nodes usually need local supplies','Neglecting the fixed, uniform node-to-node latency budget when synchronizing microphones for active noise control']::text[],ARRAY['Wiring a distributed microphone array for in-car communication and voice assistants','Feeding reference and error microphone signals to a road noise cancellation processor','Connecting multiple smart amplifier modules to a head unit with minimal cabling']::text[],'intermediate','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Automotive Audio Bus (A2B)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b2f8fbba-7c4e-5ef8-b690-520f3f0c9cf8','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b2f8fbba-7c4e-5ef8-b690-520f3f0c9cf8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b2f8fbba-7c4e-5ef8-b690-520f3f0c9cf8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6d13d957-9577-5239-ba88-f623c25ba5a7','Media Oriented Systems Transport (MOST)','MOST is an automotive multimedia networking standard that carries synchronous streaming audio and video, packet-based asynchronous data, and a dedicated control channel over a ring topology, historically implemented on plastic optical fiber and later on electrical unshielded twisted pair. A timing master locks the frame rate to the audio sample rate, and successive generations, commonly labelled by their gross bandwidth in megabits per second, increase channel capacity and add isochronous transport for packetized and IP traffic.','MOST is an in-car network for media. It moves audio, video, and control data together. Devices connect in a ring, often over an optical fiber. It keeps sound and picture in step across the car.','It provides a synchronized, low-jitter backbone so head units, amplifiers, changers, tuners, displays, and telematics units can share high-quality streaming media and coordinated control without the timing drift and bandwidth limits of general-purpose vehicle buses.','Technicians encounter MOST in infotainment rings of many 2000s and 2010s premium vehicles, where a broken fiber, an unwoken node, or a device that fails to release the ring can silence the whole network and require diagnostic ring-break analysis.','Automotive Audio Systems',ARRAY['Automotive Audio Bus (A2B)','Automotive Ethernet','Plastic optical fiber','Isochronous transfer','Infotainment head unit']::text[],ARRAY['Confusing the generation labels with usable audio-only throughput, since bandwidth is shared among synchronous, asynchronous, and control channels','Assuming any single powered-down or faulty node leaves the rest of the ring working, when it can break the entire loop','Treating MOST as interchangeable with CAN, which lacks the synchronous streaming and bandwidth MOST provides']::text[],ARRAY['Diagnosing a dead infotainment system caused by a single node failing to wake the ring','Routing streaming audio and video between a head unit, amplifier, and rear-seat displays','Migrating a legacy fiber multimedia network toward automotive Ethernet']::text[],'intermediate','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Media Oriented Systems Transport (MOST)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6d13d957-9577-5239-ba88-f623c25ba5a7','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6d13d957-9577-5239-ba88-f623c25ba5a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6d13d957-9577-5239-ba88-f623c25ba5a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0433f518-8f28-5425-af75-92ab9c437083','Road Noise Cancellation (RNC)','Road noise cancellation is an active control technique that attenuates low-frequency structure-borne cabin noise generated by tire, road, and suspension interaction. Accelerometers on suspension or body members provide coherent reference signals, cabin error microphones sense residual pressure, and an adaptive controller, typically a multichannel filtered-reference least-mean-squares algorithm, drives the audio loudspeakers to produce anti-noise that destructively sums with the primary noise at the listener positions.','Road noise cancellation lowers the rumble from tires and the road. Sensors and microphones measure the noise. A processor builds an opposite sound wave. Speakers play it to cancel the noise near your ears.','It targets the broadband, non-tonal low-frequency road boom that passive damping and mass treatments cannot economically suppress, improving cabin comfort while saving the weight and cost of added sound-deadening material.','It is deployed in production vehicles that share the audio amplifier and speakers with the entertainment system, requiring careful placement of accelerometers and error microphones, secondary-path modeling, and validation that the algorithm does not add noise where coherence is poor.','Automotive Audio Systems',ARRAY['Engine Harmonic Cancellation (EHC)','Active Sound Management (ASM)','Filtered-x LMS algorithm','Secondary path modeling','Structure-borne noise']::text[],ARRAY['Expecting broadband cancellation everywhere, when active control is only effective at low frequencies and near the error sensors','Using reference signals poorly correlated with the actual road noise, which limits achievable attenuation','Ignoring secondary-path changes with cabin loading and temperature, causing the adaptive filter to diverge or add noise']::text[],ARRAY['Reducing low-frequency road boom on coarse asphalt without adding mass','Tuning accelerometer reference locations on a new suspension design','Validating that cancellation does not degrade sound at rear seats away from error microphones']::text[],'advanced','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Road Noise Cancellation (RNC)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0433f518-8f28-5425-af75-92ab9c437083','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0433f518-8f28-5425-af75-92ab9c437083') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0433f518-8f28-5425-af75-92ab9c437083');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c791cdf-5a1a-50d7-b19c-f67eeb4e1d2c','Engine Harmonic Cancellation (EHC)','Engine harmonic cancellation is a narrowband active control method that suppresses discrete tonal components produced by the powertrain at integer orders of rotational speed. A tachometric reference derived from engine or motor speed defines each target order frequency, and an adaptive controller synthesizes phase-inverted tones through the cabin loudspeakers so that, at the error microphones, the anti-sound cancels the offending harmonics of engine boom and drivetrain whine.','Engine harmonic cancellation removes droning engine tones. It tracks the engine speed to find those tones. The system plays an opposite sound through the speakers. This makes the cabin quieter without heavy material.','It removes objectionable engine orders such as low-frequency boom during lugging or cylinder deactivation, allowing downsized or displacement-on-demand engines to run in efficient but boomy operating regions while keeping the cabin refined.','It runs on the infotainment DSP and amplifier, phase-locked to the crankshaft speed signal on the vehicle bus; calibration engineers map which orders to cancel across the speed and load range and verify performance at multiple seat microphones.','Automotive Audio Systems',ARRAY['Road Noise Cancellation (RNC)','Engine Harmonic Enhancement (EHE)','Active Sound Management (ASM)','Engine order','Cylinder deactivation']::text[],ARRAY['Confusing narrowband harmonic cancellation with broadband road noise cancellation, which needs different references and algorithms','Cancelling orders that carry desirable feedback about engine effort, producing an unnatural or disconnected feel','Assuming a single microphone yields cancellation everywhere, when nulls are localized to the error sensor positions']::text[],ARRAY['Suppressing boom when a V8 runs on four cylinders during cruise','Quieting a specific droning order that appears at highway engine speeds','Coordinating cancellation with enhancement so wanted orders remain audible']::text[],'advanced','f_n = n * (RPM / 60)','The frequency of engine order n equals the order number multiplied by the rotational speed in revolutions per second, that is revolutions per minute divided by sixty.','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Engine Harmonic Cancellation (EHC)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c791cdf-5a1a-50d7-b19c-f67eeb4e1d2c','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c791cdf-5a1a-50d7-b19c-f67eeb4e1d2c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c791cdf-5a1a-50d7-b19c-f67eeb4e1d2c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '396b47f7-68ba-585c-8135-6b15b5857dd3','Engine Harmonic Enhancement (EHE)','Engine harmonic enhancement is an active sound-shaping method that reinforces or synthesizes selected powertrain orders through the cabin loudspeakers to craft a target interior sound signature. Using a rotational-speed reference, the system generates tones at chosen engine orders with level and phase scheduled against speed, load, and pedal position, adding warmth or sportiness that the physical powertrain, especially a downsized or electric one, does not naturally produce.','Engine harmonic enhancement adds or boosts engine tones. It uses the speakers to shape the engine''s sound. Quiet or electric cars can be made to sound sporty. The sound follows engine speed so it feels real.','It restores or designs an emotional and informative engine sound where mechanical noise is weak, giving the driver consistent auditory feedback about effort and speed and reinforcing brand sound identity.','Sound designers author order-level maps in the audio DSP that respond to throttle and speed, then tune balance and phase across seats; it is common in performance trims and in electric vehicles that offer a synthesized drive sound.','Automotive Audio Systems',ARRAY['Engine Harmonic Cancellation (EHC)','Active Sound Management (ASM)','Engine order','Sound design','Electric vehicle sound synthesis']::text[],ARRAY['Assuming enhancement is merely amplified real engine noise, when much of the content is synthesized and mapped to inputs','Scheduling order levels that disagree with actual acceleration, producing a fake or disconnected impression','Overlapping enhancement and cancellation on the same orders so they fight each other']::text[],ARRAY['Giving an electric vehicle an optional synthesized performance sound','Adding sporty character to a downsized turbocharged engine','Blending enhanced and cancelled orders for a coherent interior signature']::text[],'advanced','f_n = n * (RPM / 60)','The reinforced tone at engine order n has a frequency equal to the order number times the rotational speed in revolutions per second, meaning revolutions per minute divided by sixty.','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Engine Harmonic Enhancement (EHE)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '396b47f7-68ba-585c-8135-6b15b5857dd3','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='396b47f7-68ba-585c-8135-6b15b5857dd3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='396b47f7-68ba-585c-8135-6b15b5857dd3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c8a4cdd5-a6c5-556a-92a0-abdc98080d4f','Active Sound Management (ASM)','Active sound management is the coordinated framework that combines active noise cancellation and active sound enhancement, together with equalization and level control, to govern a vehicle''s interior acoustic character. Running on shared audio processing and loudspeaker resources, it arbitrates cancellation of unwanted road and engine components against reinforcement of desirable powertrain tones, delivering a deliberately designed, condition-dependent cabin soundscape rather than isolated point features.','Active sound management shapes the sound inside a car. It can cancel unwanted noise and add wanted tones. Software and the car speakers do this work together. The goal is a calm, tuned cabin sound.','It unifies otherwise separate cancellation and enhancement functions so they share sensors, DSP, and speakers without conflict, letting an automaker tune both quietness and sound identity as one consistent experience.','It appears as an umbrella feature integrating road noise cancellation, engine harmonic cancellation, and enhancement in a single audio platform, where calibration teams balance comfort, feedback, and brand character across driving conditions.','Automotive Audio Systems',ARRAY['Road Noise Cancellation (RNC)','Engine Harmonic Cancellation (EHC)','Engine Harmonic Enhancement (EHE)','In-Car Communication (ICC)','Cabin equalization']::text[],ARRAY['Treating it as a single algorithm rather than an orchestrating layer over several active functions','Assuming cancellation and enhancement never interact, when both use the same speakers and must be arbitrated','Expecting it to fix mechanical noise problems that are better solved at the source']::text[],ARRAY['Coordinating cancellation and enhancement so they do not compete for speaker headroom','Switching cabin sound character between comfort and sport drive modes','Integrating communication assistance with noise control on one audio platform']::text[],'intermediate','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Active Sound Management (ASM)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c8a4cdd5-a6c5-556a-92a0-abdc98080d4f','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c8a4cdd5-a6c5-556a-92a0-abdc98080d4f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c8a4cdd5-a6c5-556a-92a0-abdc98080d4f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '579d9a2f-ac06-5f4b-a381-168d6f13b4b6','In-Car Communication (ICC)','In-car communication is an audio system that captures a talking occupant''s voice with seat-zone microphones and reproduces it, with gain and delay processing, through loudspeakers near other seats to improve intelligibility between rows. It applies acoustic echo cancellation, feedback suppression, and speed-dependent gain so front and rear occupants converse without shouting, particularly in large cabins and at high road speeds.','In-car communication helps people in a car talk. Microphones pick up a talker''s voice. Speakers near other seats play it a bit louder. This helps front and back seats hear each other.','It overcomes the loss of direct speech across a noisy cabin by electronically relaying and boosting occupants'' voices toward the seats that need them, reducing listening effort and vocal strain on long or fast drives.','It runs on the infotainment DSP using the same distributed microphones and speakers as hands-free calling, and must be tuned to avoid howling feedback, unnatural delay, and re-amplification of road noise.','Automotive Audio Systems',ARRAY['Acoustic echo cancellation','Automotive Audio Bus (A2B)','Feedback suppression','Beamforming microphone array','Headrest Speaker']::text[],ARRAY['Setting relay gain too high, which causes acoustic feedback howl between microphones and speakers','Amplifying background road noise along with speech because of weak noise suppression','Adding excessive delay so the relayed voice sounds detached from the live talker']::text[],ARRAY['Helping a driver speak with third-row passengers in a large SUV','Maintaining conversation clarity at highway speed with high road noise','Sharing microphones between voice calls and occupant-to-occupant relay']::text[],'intermediate','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='In-Car Communication (ICC)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '579d9a2f-ac06-5f4b-a381-168d6f13b4b6','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='579d9a2f-ac06-5f4b-a381-168d6f13b4b6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='579d9a2f-ac06-5f4b-a381-168d6f13b4b6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b7d8e94d-b709-5267-8edd-06ceac3eb5dd','Acoustic Vehicle Alerting System (AVAS)','An Acoustic Vehicle Alerting System is a regulated exterior sound emitter fitted to electric and hybrid vehicles to make them audible to pedestrians when propulsion noise is otherwise inaudible. Governing regulations require a continuous sound during standstill, forward motion up to a defined low-speed threshold, and reversing, with specified minimum sound pressure levels in prescribed frequency bands and a pitch or level that varies with speed; recent rulemaking removed the previously permitted driver pause switch.','AVAS makes a sound for quiet electric cars. These cars are almost silent at low speed. The sound warns nearby people that a car is close. It plays at low speeds and while backing up.','It protects pedestrians, cyclists, and especially blind and low-vision people by giving quiet electric and hybrid vehicles a detectable acoustic presence in exactly the low-speed situations where tire and wind noise are insufficient.','Engineers integrate a weatherproof exterior speaker and controller that generate the alert from vehicle speed and gear signals, then verify emitted level and spectrum against the applicable standard during type approval or compliance testing.','Automotive Audio Systems',ARRAY['Pedestrian safety','Electric vehicle','Sound pressure level','Engine Harmonic Enhancement (EHE)','Type approval testing']::text[],ARRAY['UNSAFE: disabling, muting, or reducing AVAS output below the regulated minimum, which removes the warning that protects pedestrians and is prohibited','UNSAFE: installing an aftermarket sound that fails the required minimum levels or speed-dependent pitch, leaving pedestrians unable to detect the vehicle','Assuming AVAS must sound at all speeds, when it may switch off above the low-speed threshold where tire and wind noise suffice','Confusing the exterior pedestrian alert with interior engine sound enhancement, which is unrelated to pedestrian safety']::text[],ARRAY['Verifying alert sound pressure levels against the standard during vehicle type approval','Ensuring the alert continues at standstill and while reversing','Confirming the sound pitch or level rises with vehicle speed to convey approach']::text[],'intermediate','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Vehicle Alerting System (AVAS)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b7d8e94d-b709-5267-8edd-06ceac3eb5dd','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b7d8e94d-b709-5267-8edd-06ceac3eb5dd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b7d8e94d-b709-5267-8edd-06ceac3eb5dd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '678270f8-0256-5366-8a3b-ff60d501fe77','Headrest Speaker','A headrest speaker is a loudspeaker built into or mounted near a seat''s headrest so that reproduced sound reaches one occupant''s ears at close range. Its near-field placement supports personal audio zones, private telephony, navigation prompts, and delivery of relayed speech, and it is often combined with signal processing that limits spill into neighboring seats to create localized listening.','A headrest speaker sits in or near the seat''s headrest. It plays sound close to one person''s ears. It can give private calls or a personal audio zone. Each seat can hear something different.','By placing a loudspeaker driver close to the listener, it delivers personal and communication audio efficiently and helps isolate content to one seat, enabling private calls, alerts, and per-seat program without disturbing others.','It is used for hands-free call audio, turn-by-turn prompts, and individual sound zones in premium and electric vehicles, and it serves as the reproduction point for in-car communication relayed to a specific occupant.','Automotive Audio Systems',ARRAY['Seat-Centric Audio','In-Car Communication (ICC)','Personal sound zone','Near-field loudspeaker','Acoustic crosstalk cancellation']::text[],ARRAY['Expecting full-range bass from a small headrest driver, which needs cabin subwoofers for low frequencies','Assuming perfect isolation, when audio still leaks to adjacent seats without added crosstalk control','Ignoring the short listener distance when setting levels, which can make output uncomfortably loud']::text[],ARRAY['Delivering a private phone call to only the driver''s seat','Playing navigation prompts near the driver without interrupting rear entertainment','Reproducing relayed speech to a specific occupant for in-car communication']::text[],'beginner','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Headrest Speaker');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '678270f8-0256-5366-8a3b-ff60d501fe77','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='678270f8-0256-5366-8a3b-ff60d501fe77') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='678270f8-0256-5366-8a3b-ff60d501fe77');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '50b906f6-cba3-507f-b971-77d1636865e0','Seat-Centric Audio','Seat-centric audio is a vehicle sound-system design philosophy that optimizes reproduction around each individual seating position rather than a single averaged cabin listening area. It uses per-seat speaker placement, headrest or near-field drivers, individual equalization and delay, and sound-zoning processing so occupants can receive independently tuned or entirely separate audio content at their own seat.','Seat-centric audio tunes sound for each seat. Older systems aimed for one good spot in the car. This design gives every seat its own good sound. Each person can set their own volume or program.','It solves the compromise of a single sweet spot by tailoring level, timing, and spectrum to each occupant, enabling personal listening zones, per-seat calls, and independent program selection within the shared cabin.','It guides speaker layout and DSP tuning in premium and electric vehicles, combining door, headrest, and zone speakers with per-seat equalization, and underpins features such as individual sound zones and seat-directed communication.','Automotive Audio Systems',ARRAY['Headrest Speaker','Personal sound zone','In-Car Communication (ICC)','Vehicle Cabin Gain','Cabin equalization']::text[],ARRAY['Assuming more speakers alone create seat isolation without zoning signal processing','Neglecting acoustic leakage between zones, which limits achievable separation in a shared cabin','Optimizing only the driver seat and treating the design as complete']::text[],ARRAY['Letting front and rear occupants play different audio at once','Tuning per-seat equalization and delay for individual listening','Building personal sound zones that limit spill between seats']::text[],'intermediate','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seat-Centric Audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '50b906f6-cba3-507f-b971-77d1636865e0','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='50b906f6-cba3-507f-b971-77d1636865e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='50b906f6-cba3-507f-b971-77d1636865e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '41f3227a-0b65-5eaf-8af0-1a4f10b328ef','Vehicle Cabin Gain','Vehicle cabin gain is the low-frequency acoustic reinforcement that arises because a vehicle interior is small compared with the wavelengths of deep bass. Below the cabin''s lowest acoustic resonance the enclosed volume behaves as a pressure chamber, so sound pressure tracks diaphragm displacement and rises as frequency falls, producing a boost that increases at roughly twelve decibels per octave toward the low end and augments a subwoofer''s in-car response.','A car cabin is a small sealed space. This boosts deep bass sounds inside it. As the tone gets lower, the bass gets louder. So car speakers make strong bass with little effort.','It explains why modest subwoofers deliver strong bass inside cars and lets designers exploit the interior''s natural low-frequency lift instead of relying solely on driver excursion and amplifier power.','System tuners account for cabin gain when choosing subwoofer size, enclosure alignment, and equalization, subtracting the interior boost so the in-car low-frequency response stays balanced rather than boomy.','Automotive Audio Systems',ARRAY['Pressure chamber effect','Sealed enclosure alignment','Subwoofer','Room gain','Cabin equalization']::text[],ARRAY['Ignoring cabin gain and over-sizing the subwoofer, producing excessive, boomy low bass in the car','Assuming the same free-field response holds inside the cabin, where the interior adds a rising low-frequency lift','Treating the boost as flat, when it grows steeper as frequency decreases']::text[],ARRAY['Selecting a smaller sealed subwoofer that still yields deep bass in a car','Applying low-frequency equalization to tame excess cabin boost','Comparing a driver''s free-field response with its measured in-car response']::text[],'intermediate','p = rho*c^2*S*x / V  =>  ~ +12 dB/octave as f -> 0','In the pressure-chamber region the internal sound pressure equals air density times sound speed squared times diaphragm area times displacement divided by cabin volume; because far-field-flat drivers move greater displacement as frequency falls, the in-cabin level rises by about twelve decibels per octave toward low frequencies.','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vehicle Cabin Gain');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '41f3227a-0b65-5eaf-8af0-1a4f10b328ef','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='41f3227a-0b65-5eaf-8af0-1a4f10b328ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='41f3227a-0b65-5eaf-8af0-1a4f10b328ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83c3a95d-5630-5a84-97be-7b633529489f','Noise-Compensated Volume Control','Noise-compensated volume control automatically adjusts playback level, and sometimes tonal balance, to maintain consistent perceived loudness as cabin background noise changes. It derives a noise estimate from vehicle speed, or from a microphone measuring actual sound pressure, or a fusion of both, then raises and lowers gain, and may lift bands most masked by road noise, so the program stays intelligible without the occupant constantly resetting the volume.','Cars get louder as they go faster. This feature raises the volume to match. It uses speed or a microphone to sense the noise. The music stays easy to hear without tweaking.','It preserves a stable listening experience across changing driving conditions by tracking background noise and compensating gain, reducing the distraction of manually chasing the volume knob as speed and road surface vary.','Implemented in head units and amplifier DSP, it is tuned with a gain-versus-speed curve or a microphone-based loop, and calibrators set attack and release times to respond smoothly without pumping or overshoot.','Automotive Audio Systems',ARRAY['Equal-loudness contour','Active Sound Management (ASM)','Automatic gain control','Cabin equalization','Road Noise Cancellation (RNC)']::text[],ARRAY['Setting too aggressive a response, so the level pumps audibly with every speed change','Relying only on speed when wind, tires, or open windows change the real noise independently','Confusing loudness compensation for noise with fixed equal-loudness tone contouring at low volume']::text[],ARRAY['Keeping music intelligible as a car accelerates onto a highway','Compensating added noise when a window is opened using a cabin microphone','Tuning attack and release so the level changes are not distracting']::text[],'intermediate','','','a4f67192-6af2-411b-8f26-4df4044a3a07' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise-Compensated Volume Control');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83c3a95d-5630-5a84-97be-7b633529489f','a4f67192-6af2-411b-8f26-4df4044a3a07',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83c3a95d-5630-5a84-97be-7b633529489f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83c3a95d-5630-5a84-97be-7b633529489f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3ce13fa2-4c93-5443-8378-80bfe90e1df8','Cockpit Voice Recorder (CVR)','A crash-protected flight recorder that continuously captures flight-deck audio on several dedicated channels, including each pilot''s headset and microphone audio, the passenger-address and additional crew stations, and a cockpit area microphone that picks up ambient sound. The audio is written to a solid-state memory module inside an armored, fire- and immersion-resistant enclosure fitted with an underwater locator beacon, letting investigators reconstruct crew communication and cockpit acoustics. Current designs conform to standards such as EUROCAE ED-112A and FAA TSO-C123, with newer units required to retain up to twenty-five hours of recording.','A cockpit voice recorder saves the sounds inside the flight deck. It keeps what the pilots say and the noises around them. The audio sits in a tough, crash-proof box. A beacon helps crews find it underwater. Investigators use the sound to learn what happened.','It preserves an accurate audio record of the final phase of flight so investigators can determine crew actions, warnings, and communication leading up to an accident or serious incident.','Technicians test each CVR channel, verify recording quality and area-microphone pickup, service the underwater locator beacon, and perform regulated downloads or bulk erasures; investigators recover the memory module after a crash.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Cockpit Area Microphone (CAM)','Flight Data Recorder (FDR)','Underwater Locator Beacon','Flight interphone','EUROCAE ED-112A']::text[],ARRAY['Assuming a CVR keeps the whole flight; older units overwrite on a short loop such as thirty minutes or two hours','Confusing the CVR with the flight data recorder, which stores flight parameters rather than audio','UNSAFE: pulling the CVR circuit breaker or erasing the recording after an incident when regulations require the audio be preserved']::text[],ARRAY['Accident investigators recover the crash-protected module and synchronize its audio with the flight data recorder','A technician runs a scheduled CVR functional check and confirms every channel records clearly','The crew uses the bulk-erase function only on the ground, with the parking brake set, after a normal flight']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cockpit Voice Recorder (CVR)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3ce13fa2-4c93-5443-8378-80bfe90e1df8','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3ce13fa2-4c93-5443-8378-80bfe90e1df8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3ce13fa2-4c93-5443-8378-80bfe90e1df8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7e1b8640-ed1b-5c81-b212-dce70232b630','Cockpit Area Microphone (CAM)','A dedicated open microphone mounted on the flight deck, usually in the overhead panel or glareshield, that feeds ambient cockpit sound to one channel of the cockpit voice recorder. It captures crew conversation not carried over the intercom, aural warnings, switch and control movements, engine and airflow noise, and other acoustic cues, giving investigators context and timing that individual boom or mask microphones cannot provide.','This is an always-on microphone in the cockpit. It feeds one track of the voice recorder. It catches talking, alarms, switch clicks, and background noise. The other tracks only hold each pilot''s own microphone. Investigators use it to hear the whole room.','It records the general acoustic environment of the flight deck so investigators can hear warnings, spoken words, and mechanical sounds that reveal the sequence of events during an occurrence.','Technicians check the CAM channel during CVR functional tests, confirming that speech intelligibility and background sounds are captured; weak or muffled CAM audio is a common recording-quality finding.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Cockpit Voice Recorder (CVR)','Hot Microphone (Hot Mic)','Aural Warning System','Flight interphone']::text[],ARRAY['Thinking the CAM records only speech; it also captures alarms, alerts, and mechanical noise','Believing the crew can mute the CAM; it is a continuous, non-switched recorder input','Obstructing or misplacing the microphone so cockpit speech becomes unintelligible on the recording']::text[],ARRAY['Investigators isolate the CAM track to time an aural warning against crew callouts','A technician confirms the area microphone captures clear speech during a recording-quality inspection','Analysts identify a specific switch or lever movement from sounds on the CAM channel']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cockpit Area Microphone (CAM)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7e1b8640-ed1b-5c81-b212-dce70232b630','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7e1b8640-ed1b-5c81-b212-dce70232b630') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7e1b8640-ed1b-5c81-b212-dce70232b630');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af85dab0-c8c8-5275-ba50-632d40465cae','Audio Control Panel (ACP)','A flight-deck station panel that lets each crew member select and mix the audio routed to their headset and boom microphone and choose which transmitter is keyed. Reception controls adjust the volume of individual radios, navigation-aid identifiers, and interphone lines, while a transmit selector directs push-to-talk audio to the chosen radio, interphone, or passenger address. Each crew station has its own panel so members can monitor different combinations independently.','The audio control panel manages a pilot''s sound. Each knob turns one radio or aid up or down. A transmit switch picks which radio the pilot talks on. Every crew seat has its own panel. Pilots can listen to different mixes at once.','It gives each crew member independent control over what they hear and where they transmit, centralizing radio, navigation, and interphone audio management at the flight-deck station.','Pilots set monitoring levels, verify a navigation-aid identifier, and select the correct transmitter before keying; avionics technicians begin troubleshooting dead radios or transmit faults at this panel.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Flight interphone','Push-to-talk (PTT)','VHF radio','Cabin interphone','Navigation receiver']::text[],ARRAY['Transmitting on the wrong radio because the transmit selector was left on a previous source','Missing a navigation identifier because its reception knob was turned fully down','Confusing the several reception monitor selectors with the single transmit selector']::text[],ARRAY['A pilot selects the VHF transmit position and checks the volume before making a call','A first officer monitors two radios and a navigation ident at once on the panel','A technician traces a no-sidetone complaint through the audio control panel wiring']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio Control Panel (ACP)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af85dab0-c8c8-5275-ba50-632d40465cae','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af85dab0-c8c8-5275-ba50-632d40465cae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af85dab0-c8c8-5275-ba50-632d40465cae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'efa23032-89fb-5585-9273-7cb3613d41cb','Flight Interphone','The internal aircraft communication system that interconnects the flight-deck crew stations and provides a wired link to ground personnel through a nose-gear or external service jack. Accessed through the audio control panels, it lets pilots talk to one another and to maintenance or pushback crews without keying an external radio, and its audio is normally recorded by the cockpit voice recorder.','The flight interphone is a private phone line on the plane. Pilots use it to talk to each other. They can also reach ground crew through a plug near the nose. No outside radio is needed. The voice recorder usually saves these calls.','It provides reliable crew-to-crew and crew-to-ground voice communication on the aircraft, separate from external radio, for coordination during flight and ground operations.','Ground crew plug a headset into the external interphone jack to talk with the flight deck during pushback and engine start, while pilots use it for intra-cockpit coordination.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Audio Control Panel (ACP)','Cabin interphone','Service interphone','Cockpit Voice Recorder (CVR)','Ground crew headset']::text[],ARRAY['Confusing the flight interphone with the cabin or service interphone, which serve cabin and maintenance crews','Forgetting to select the interphone transmit position, so speech goes out over a radio instead','Assuming ground personnel can hear the flight deck without the external jack connected']::text[],ARRAY['A pushback crew and the captain coordinate brake release over the interphone','Two pilots use the interphone to run a checklist over intercom in a noisy cockpit','A mechanic connects at the nose-gear jack to confirm a system with the flight deck']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flight Interphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'efa23032-89fb-5585-9273-7cb3613d41cb','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='efa23032-89fb-5585-9273-7cb3613d41cb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='efa23032-89fb-5585-9273-7cb3613d41cb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14575552-e88b-519c-aec9-8e290f7e609d','Hot Microphone (Hot Mic)','A microphone path that stays live continuously without a push-to-talk action, passing everything it hears straight through to a recorder or communication channel. In aviation the cockpit area microphone, and in some operations a boom microphone, are run hot to feed the cockpit voice recorder; the term also describes an inadvertently keyed radio that transmits unintended cockpit audio.','A hot mic is a microphone that is always on. You do not press a button to use it. It sends sound all the time. In a cockpit it can feed the voice recorder. But an accidental hot mic can send private talk over the radio.','Running a microphone hot ensures continuous capture of speech and ambient sound for recording or monitoring, without relying on the crew to key a switch.','The CVR area microphone is intentionally hot, while crews and technicians also watch for an unintended hot mic that blocks a radio frequency by transmitting continuously.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Cockpit Area Microphone (CAM)','Push-to-talk (PTT)','Stuck Microphone Protection','Cockpit Voice Recorder (CVR)']::text[],ARRAY['UNSAFE: leaving a transmit switch keyed so a hot mic blocks the radio frequency and prevents other calls','Assuming a hot mic captures only intended speech rather than all cockpit conversation and noise','Confusing an intentional recorder hot mic with an accidental stuck transmission']::text[],ARRAY['A boom microphone is set hot so the recorder captures a crew callout without a key press','Controllers hear continuous cockpit chatter because a transmit switch is stuck live','An investigator relies on always-on area-microphone audio to time an event']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hot Microphone (Hot Mic)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14575552-e88b-519c-aec9-8e290f7e609d','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14575552-e88b-519c-aec9-8e290f7e609d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14575552-e88b-519c-aec9-8e290f7e609d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '912546c0-9e58-5677-8670-b03bac435dc9','Stuck Microphone Protection','A radio or audio-system safeguard that limits how long a transmitter may remain continuously keyed, guarding against a jammed push-to-talk switch or hot microphone that would otherwise hold a frequency open and block all other traffic. A transmit time-out timer terminates the carrier after a preset interval, often with an audible or visual alert, so the shared channel is released for other users.','This feature stops a radio from getting stuck on. A jammed button can hold the channel open. That blocks everyone else from talking. A timer ends the transmission after a set time. Then the frequency is free again.','It prevents a single faulty or held microphone from monopolizing a shared radio frequency, preserving communication for other aircraft, vessels, and controllers.','Transceivers with a transmit time-out timer automatically drop the carrier after a preset interval of continuous keying, and technicians confirm the function during radio checks.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Hot Microphone (Hot Mic)','Push-to-talk (PTT)','Transmit time-out timer','VHF radio','Audio Control Panel (ACP)']::text[],ARRAY['Believing every radio has this feature; many simple transceivers transmit indefinitely when keyed','UNSAFE: ignoring a suspected stuck transmission instead of switching the transmitter off, leaving the frequency blocked','Confusing the transmit time-out with an ordinary squelch or volume control']::text[],ARRAY['A time-out timer cuts a transmission after a jammed switch keys the radio too long','A dispatcher''s console releases a channel automatically when a console microphone sticks','A technician verifies the transmit cutoff time during a scheduled radio bench check']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stuck Microphone Protection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '912546c0-9e58-5677-8670-b03bac435dc9','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='912546c0-9e58-5677-8670-b03bac435dc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='912546c0-9e58-5677-8670-b03bac435dc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '12f59bee-e1b0-5d45-a1e4-f13c4545249c','Aural Warning System','The aircraft subsystem that delivers audible alerts to the crew, including discrete tones, chimes, bells, clackers, synthetic voice callouts, and spoken messages, prioritized by urgency. Integrated with the warning and caution logic of systems such as EICAS or ECAM, ground-proximity and terrain awareness, and stall protection, it directs attention to conditions the crew must notice immediately, complementing visual warnings.','This system makes warning sounds for the crew. It uses tones, chimes, bells, and spoken alerts. Loud, urgent sounds mean act now. It works with terrain, stall, and system alerts. The sounds grab attention faster than lights.','It provides immediate, attention-getting audible cues so the flight crew detects hazards and abnormal conditions quickly, even when looking away from the visual displays.','Pilots hear the landing-gear horn, overspeed clacker, stall warning, and spoken alerts such as terrain or pull-up callouts, while technicians test these annunciations during system checks.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Master Warning','Ground Proximity Warning System (GPWS)','Terrain Awareness and Warning System (TAWS)','Stall warning','EICAS/ECAM']::text[],ARRAY['Treating the most-urgent reserved sounds as ordinary alerts rather than immediate-action warnings','Assuming every alert is voice; many are tones, chimes, or clackers tied to specific systems','UNSAFE: silencing or pulling the breaker on a required aural warning such as the stall or ground-proximity alert']::text[],ARRAY['A terrain-awareness callout sounds and the crew executes an immediate escape maneuver','The gear-up horn warns of a landing configuration error on approach','A technician cycles the warning logic to confirm each tone and voice message plays']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aural Warning System');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '12f59bee-e1b0-5d45-a1e4-f13c4545249c','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='12f59bee-e1b0-5d45-a1e4-f13c4545249c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='12f59bee-e1b0-5d45-a1e4-f13c4545249c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6fa725a7-8846-5759-b59b-9656dfb482a5','Cabin Interphone','The internal telephone-style system that links cabin-crew stations to one another and to the flight deck, letting flight attendants place and receive calls and coordinate with the pilots. It commonly shares handsets and attendant panels with the passenger-address system and is used for routine coordination and for emergency notification between the cabin and the cockpit.','The cabin interphone is the plane''s inside phone for the crew. Flight attendants use it to call each other. They also use it to call the pilots. The same handsets often make cabin announcements. It matters most during an emergency.','It gives cabin crew a dedicated voice link among cabin stations and to the flight deck for service coordination and emergency communication.','A flight attendant lifts an interphone handset, dials the flight deck or another station, and speaks; the same handset switches to the passenger-address mode for announcements.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Flight interphone','Passenger Address (PA) system','Attendant panel','Audio Control Panel (ACP)','Service interphone']::text[],ARRAY['Confusing the cabin interphone with the flight interphone used by pilots and ground crew','Selecting passenger-address mode when a private call was intended, broadcasting to the whole cabin','Assuming the interphone reaches ground personnel, a task handled by the service interphone']::text[],ARRAY['A purser calls the flight deck to report a cabin issue before departure','Cabin crew coordinate a medical response between galleys over the interphone','An attendant switches a handset from interphone to passenger address for a boarding announcement']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cabin Interphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6fa725a7-8846-5759-b59b-9656dfb482a5','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6fa725a7-8846-5759-b59b-9656dfb482a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6fa725a7-8846-5759-b59b-9656dfb482a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '57d6043a-2d48-5e67-b88d-41f818a1a2ea','Sound Reception System','A shipboard acoustic-electronic aid required on vessels with a fully enclosed navigating bridge, using external microphones to capture sound signals from outside and reproduce them for the officer of the watch. It receives signals across the audio band used for maritime whistles, indicates the approximate direction of an incoming sound, and reproduces it inside the wheelhouse above the ambient noise so a proper aural lookout is maintained.','On ships with a closed bridge, crews cannot hear outside. This system uses outdoor microphones to fix that. It plays horn and whistle signals inside. It also shows roughly where each sound comes from. That helps the watch officer avoid a collision.','It restores the aural lookout lost when the bridge is fully enclosed, letting the officer of the watch hear and roughly locate external whistle and fog signals for collision avoidance.','On an enclosed-bridge vessel the officer hears another ship''s fog signal through bridge loudspeakers and reads its rough bearing, forward or abaft the beam and to port or starboard, on a display.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Enclosed bridge','Sound signal','Collision avoidance','Wheelhouse loudspeaker','COLREGs']::text[],ARRAY['Setting the reproduced volume so low that external signals fall below the bridge noise and are missed','Assuming the system gives an exact bearing; it indicates only approximate direction and side','Treating it as optional on an enclosed bridge, where it substitutes for the open-air aural lookout']::text[],ARRAY['In fog the watch officer hears a crossing vessel''s signal through the bridge speaker','The directional display shows a horn is forward of the beam on the port side','A surveyor confirms the reproduced level stays audible above bridge equipment noise']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound Reception System');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '57d6043a-2d48-5e67-b88d-41f818a1a2ea','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='57d6043a-2d48-5e67-b88d-41f818a1a2ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='57d6043a-2d48-5e67-b88d-41f818a1a2ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '60a6066d-c333-5ba1-a4f5-d7ed8b54eaa7','General Emergency Alarm System','A shipwide audible alarm required by international convention that summons passengers and crew to their muster stations in an emergency. It sounds a distinctive signal of seven or more short blasts followed by one long blast on the ship''s whistle and on internal bells or klaxons, must be audible throughout accommodation and working spaces, and is normally backed by the public-address system for spoken instructions.','This alarm calls everyone on a ship during an emergency. The signal is seven short blasts and one long blast. Bells, horns, or klaxons sound it across the ship. It must be loud enough to wake sleeping people. Crew and passengers then go to their muster stations.','It provides an unmistakable, ship-wide cue that starts the emergency response and sends everyone to assigned muster or lifeboat stations.','During a drill or a real emergency the officer activates the alarm, and the seven-short-then-one-long pattern sounds throughout the vessel, followed by public-address instructions.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Muster station','Public Address (PA) system','Abandon ship','Ship''s whistle','SOLAS']::text[],ARRAY['Confusing the general emergency signal with the separate abandon-ship order, which is given verbally','Assuming one long blast alone is the signal rather than seven short blasts then one long','UNSAFE: disabling or muting the alarm in occupied spaces, leaving people without warning in an emergency']::text[],ARRAY['A weekly drill begins with the general alarm and a muster of all hands','The officer of the watch sounds the alarm after a fire is reported below decks','A surveyor checks that the alarm is audible in every cabin and machinery space']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='General Emergency Alarm System');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '60a6066d-c333-5ba1-a4f5-d7ed8b54eaa7','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='60a6066d-c333-5ba1-a4f5-d7ed8b54eaa7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='60a6066d-c333-5ba1-a4f5-d7ed8b54eaa7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5b545f6c-d46d-5bc9-987b-8ae3227810e0','Voyage Data Recorder Audio','The audio component of a ship''s voyage data recorder, comprising bridge microphones that capture ambient sound and spoken orders at every bridge workstation plus a separate channel recording VHF radio communications. Stored with navigational data on a protected, tamper-resistant capsule, this audio lets investigators reconstruct bridge conversation, commands, and radio traffic after a marine casualty, in the same role as an aircraft cockpit voice recorder.','A voyage data recorder is a ship''s black box. Microphones on the bridge record talk and background sound. Another channel saves the VHF radio calls. The audio is kept in a protected capsule. Investigators use it after an accident at sea.','It preserves bridge speech and radio communications alongside voyage data so investigators can reconstruct the human actions and orders surrounding a marine incident.','After a collision or grounding, investigators extract the capsule and review synchronized bridge audio, VHF traffic, radar, and position data.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Voyage Data Recorder (VDR)','Bridge microphone','Protective capsule','Cockpit Voice Recorder (CVR)','VHF communications']::text[],ARRAY['Assuming the recorder stores only navigation data; bridge audio and VHF communications are integral channels','Believing bridge microphones cover only one station; multiple workstations must be captured','UNSAFE: failing to preserve or save the recording after an incident, letting the protected audio be overwritten before retrieval']::text[],ARRAY['Investigators recover the float-free capsule and transcribe bridge orders before a grounding','A master activates the save function immediately after a collision to protect the audio','An auditor verifies each bridge microphone captures clear speech during an annual test']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voyage Data Recorder Audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5b545f6c-d46d-5bc9-987b-8ae3227810e0','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5b545f6c-d46d-5bc9-987b-8ae3227810e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5b545f6c-d46d-5bc9-987b-8ae3227810e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cae75f15-6758-5422-92fe-1b0ee10230d6','Helmet Intercom','A short-range communication system built into or clamped onto a helmet, pairing a microphone near the mouth with speakers at the ears so a helmeted user can talk hands-free. In motorcycling these units use Bluetooth or mesh radio to link a rider and passenger or a group of riders and to bridge phone and navigation audio; motorsport, industrial, and aircrew versions use wired or dedicated wireless links.','A helmet intercom lets you talk while wearing a helmet. A small mic sits near your mouth. Speakers sit by your ears. Riders use it to chat with a passenger or group. Many link to a phone by Bluetooth.','It provides hands-free voice communication for a helmeted user, keeping the hands free for control and the head protected while riding or operating.','Motorcyclists pair two headsets over Bluetooth or mesh to talk between bikes, take calls, and hear turn-by-turn directions without stopping.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Bluetooth headset','Push-to-talk (PTT)','Boom microphone','Mesh intercom','Noise-cancelling microphone']::text[],ARRAY['Expecting long range from a Bluetooth pairing, which drops out over distance and obstacles','Mounting the microphone too far from the mouth, so wind noise overwhelms speech','Assuming all brands interconnect; proprietary systems often will not pair across makers']::text[],ARRAY['Two riders keep a group ride coordinated over a mesh intercom link','A courier answers a call hands-free through the helmet speakers while riding','A pillion passenger and rider talk over a short-range Bluetooth pairing']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Helmet Intercom');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cae75f15-6758-5422-92fe-1b0ee10230d6','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cae75f15-6758-5422-92fe-1b0ee10230d6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cae75f15-6758-5422-92fe-1b0ee10230d6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1a8251b8-dd51-51ba-90d6-c1125b98c9e0','Siren Wail Tone','An emergency-vehicle siren mode in which the pitch sweeps slowly up and down through a fixed frequency range, producing a long, drawn-out rising-and-falling cry. The gradual sweep, completing a cycle over several seconds, projects well over distance and is used for open-road response, in contrast to the faster yelp mode and the rapid hi-lo or phaser modes used in congested traffic.','The wail is the classic long siren sound. Its pitch rises and falls slowly. One up-and-down cycle takes a few seconds. The slow sweep travels far down open roads. Faster siren modes work better in heavy traffic.','The slow frequency sweep maximizes how far the warning carries on open roads, alerting distant drivers and pedestrians to an approaching emergency vehicle.','Drivers switch to wail on highways for maximum reach and to yelp when weaving through intersections, where the faster tone is easier to localize.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Yelp tone','Hi-lo tone','Electronic siren','Public-address siren','Doppler effect']::text[],ARRAY['Assuming louder alone means more noticeable; tone choice and change matter for detection in traffic','Confusing the slow wail with the faster yelp, which is preferred at intersections','Believing a steady tone carries as far; the sweeping pitch aids detection over distance']::text[],ARRAY['An ambulance runs the wail along an open highway to warn traffic far ahead','A driver switches from wail to yelp when approaching a busy intersection','A dispatcher-trained operator selects wail for a long clear-road response']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Siren Wail Tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1a8251b8-dd51-51ba-90d6-c1125b98c9e0','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1a8251b8-dd51-51ba-90d6-c1125b98c9e0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1a8251b8-dd51-51ba-90d6-c1125b98c9e0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1ae25962-857b-56a3-9fb5-f815378f55de','Siren Yelp Tone','An emergency-vehicle electronic-siren mode in which the output tone is swept rapidly up and down across roughly 800 to 1700 Hz, completing a full sweep in a fraction of a second at a nominal cycling rate of about 160 to 240 cycles per minute. The modulation is much faster than the wail mode over the same frequency band, which raises the signal''s perceived urgency and aids short-range localization, while on-axis A-weighted output typically meets the class levels of about 115 to 120 dB measured at three metres.','Yelp is a fast siren sound. The pitch sweeps up and down many times each second. It sounds more urgent than a slow wail. Drivers use it in heavy traffic and at crossings. It tells nearby cars to move right away.','It conveys heightened urgency and prompts immediate yielding at close range. The fast sweep rate is more attention-grabbing than the wail and helps listeners detect and locate an approaching vehicle in acoustically cluttered, congested environments.','An operator selects it from the siren controller, often through a horn-ring transfer button, when approaching busy intersections or slow-to-yield traffic. Installers and technicians confirm its cycle rate and on-axis output level during siren fitting and periodic sound-output testing.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Wail tone','Hi-Lo tone','Phaser tone','Electronic siren amplifier','Sound pressure level','Rumbler low-frequency siren']::text[],ARRAY['Assuming yelp is louder than wail, when the two modes share the same band and output level and differ only in sweep rate','Leaving yelp running continuously, which can desensitize nearby drivers and erode its urgency value','UNSAFE: operating high-output sirens near 115 to 120 dB at three metres without hearing protection close to the horn, or aiming the horn toward a cab, risking hearing damage']::text[],ARRAY['An ambulance switches from wail to yelp while clearing a busy crossroads','A patrol car uses yelp to prompt a slow vehicle to pull over','A technician measures on-axis output level during a post-installation siren check']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Siren Yelp Tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1ae25962-857b-56a3-9fb5-f815378f55de','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1ae25962-857b-56a3-9fb5-f815378f55de') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1ae25962-857b-56a3-9fb5-f815378f55de');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a822752a-ca44-513c-98d5-2d5ee1448213','Siren Phaser Tone','A proprietary electronic-siren tone that produces an extremely rapid, warbling frequency modulation, cycling faster than the standard yelp mode, to create a distinctive penetrating signal intended to cut through ambient traffic noise and vehicle sound insulation. Siren makers group it among their rapid tone families; its quick, science-fiction-like pitch oscillation is used to break through a listener''s habituation to conventional wail and yelp patterns. Exact frequencies and rates are manufacturer-defined rather than standardized.','Phaser is a very fast siren tone. The pitch wobbles up and down even quicker than yelp. It sounds a bit like a sci-fi ray gun. This unusual sound grabs attention in traffic. Drivers notice it when they tune out normal sirens.','It provides an alternative, highly attention-getting pattern that stands out from routine wail and yelp tones. This helps an approaching emergency vehicle be noticed by drivers who have grown used to, and now tend to ignore, common siren sounds.','An operator chooses it from the siren head-unit tone selector when standard tones are being ignored, sometimes blending it with air-horn or yelp for extra conspicuity. Installers confirm the tone exists in the amplifier''s stored library and reproduces cleanly through the speaker.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Yelp tone','Wail tone','Warble tone','Electronic siren','Air horn','Priority tone']::text[],ARRAY['Treating phaser as a standardized tone with fixed specifications, when it is a manufacturer-specific pattern that varies between siren brands','Overusing rapid tones so drivers habituate to them, which defeats the tone''s attention-getting purpose']::text[],ARRAY['An officer cycles to phaser when yelp fails to clear an intersection','A siren technician auditions each stored tone, including phaser, during bench testing']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Siren Phaser Tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a822752a-ca44-513c-98d5-2d5ee1448213','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a822752a-ca44-513c-98d5-2d5ee1448213') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a822752a-ca44-513c-98d5-2d5ee1448213');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a13d62a9-bea1-5091-89c5-a1998baefd52','Siren Hi-Lo Tone','A two-tone emergency siren mode that alternates between two fixed pitches, one higher and one lower steady tone, rather than continuously sweeping frequency, switching between them at a nominal rate of about 40 to 60 cycles per minute. Common on European emergency vehicles and used elsewhere for non-pursuit signaling and public-warning or evacuation alerts, its steady dual-pitch pattern is readily distinguished by ear from the swept wail and yelp modes.','Hi-lo jumps between two steady notes. One note is high and one is low. It does not slide smoothly like a wail. Many European ambulances and police cars use it. Some towns also use hi-lo to warn people to leave an area.','It gives a recognizable, less aggressive alternating-pitch warning that differs clearly from swept sirens. That distinct two-tone signature suits slower advisory driving and, in some regions, serves as an evacuation or public-warning cue for residents.','An operator selects it on the siren controller for measured, non-emergency movement or for community evacuation announcements. Technicians confirm both tone frequencies and the alternation rate when configuring or servicing the siren amplifier.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Wail tone','Yelp tone','Two-tone horn','Electronic siren','Public-address evacuation signal','Sound pressure level']::text[],ARRAY['Confusing hi-lo with the swept wail, when hi-lo uses two fixed pitches instead of a continuous sweep','Assuming hi-lo carries the same legal right-of-way meaning everywhere, when its use and interpretation vary by jurisdiction']::text[],ARRAY['A European ambulance runs hi-lo while moving through moderate traffic','A fire district activates a vehicle hi-lo tone to signal residents to evacuate','A technician programs the two hi-lo pitches during siren commissioning']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Siren Hi-Lo Tone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a13d62a9-bea1-5091-89c5-a1998baefd52','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a13d62a9-bea1-5091-89c5-a1998baefd52') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a13d62a9-bea1-5091-89c5-a1998baefd52');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e440232c-8b43-57ce-ba9f-4972f7dfc32e','Combustion Knock Detection','The sensing of abnormal combustion, called knock or detonation, in an internal-combustion engine by detecting the characteristic high-frequency structural vibration and in-cylinder pressure oscillation it produces. A knock event excites acoustic resonances of the combustion-chamber gas, typically in the 5 to 15 kHz range, whose fundamental frequency scales with the speed of sound in the burned gas and inversely with cylinder bore. A piezoelectric knock sensor bolted to the engine block transduces these vibrations, and the engine control unit windows the signal to the relevant crank angle, filters or spectrally analyses it near the expected knock frequency, and, on confirming knock, retards ignition timing to protect the engine.','Knock is a bad kind of burning inside an engine. It makes a sharp rattling or pinging sound. A small sensor on the engine feels these fast vibrations. The engine computer listens for them at set times. When it hears knock, it delays the spark to stop damage.','It catches damaging detonation before it harms pistons, rings, or bearings. It also lets the engine run close to the knock limit for good efficiency and power, trimming spark timing only when knock actually appears rather than de-rating all the time.','Engine-management calibrators set the knock-detection crank-angle window and frequency filters on a dynamometer. Technicians diagnose knock-sensor fault codes, verify sensor mounting torque, which affects its frequency response, and use knock feedback when tuning ignition and fuel maps.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Piezoelectric accelerometer','Detonation','Pre-ignition','Ignition timing retard','Engine control unit','Cylinder pressure transducer']::text[],ARRAY['Confusing knock, the auto-ignition of end gas after the spark, with pre-ignition, which starts before the spark, since they have different causes and remedies','Mis-torquing the knock sensor, which shifts its resonance and corrupts detection','UNSAFE: ignoring persistent knock or disabling knock control while tuning, which can rapidly destroy pistons and bearings']::text[],ARRAY['An engine control unit retards spark after detecting knock on low-octane fuel','A tuner sets the knock frequency window to match a new engine''s bore','A technician replaces a faulty knock sensor to clear a stored diagnostic code']::text[],'advanced','f_{m,n} ≈ ρ_{m,n}·c / (π·B),  ρ_{1,0} ≈ 1.841','The resonant knock frequency equals a Bessel mode constant times the speed of sound in the burned gas, divided by pi times the cylinder bore; the first circumferential mode uses a constant of about 1.841.','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Combustion Knock Detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e440232c-8b43-57ce-ba9f-4972f7dfc32e','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e440232c-8b43-57ce-ba9f-4972f7dfc32e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e440232c-8b43-57ce-ba9f-4972f7dfc32e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3e7d7dd4-2b62-5aa8-823c-ab095cda3c1b','Communications Carrier Assembly (CCA, "Snoopy Cap")','A close-fitting fabric communications cap worn by an astronaut under the pressure-suit helmet, carrying redundant microphones positioned near the mouth and earphones over the ears to provide two-way voice communication and caution-and-warning audio. As part of the extravehicular mobility unit''s communications chain, it plugs into the suit''s radio and communications equipment so the crew member can speak with mission control and other crew during launch, entry, or spacewalks. Its brown-and-white coloring gave rise to the nickname Snoopy cap.','The Snoopy cap is a soft cloth hood for astronauts. It fits under the helmet. It holds tiny microphones near the mouth and earphones at the ears. This lets the astronaut talk with mission control. It also carries warning tones inside the suit.','It holds the microphones and earphones firmly against the head so voice and warning signals stay clear no matter how the crew member moves inside the suit. The redundant microphones guard against a single microphone failing during critical operations.','A crew member dons it before suiting up for launch, re-entry, or a spacewalk. Technicians inspect and functionally check its microphones and earphones during communications-system pre-flight verification and connect it to the suit''s communications carrier for voice checks.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['Extravehicular mobility unit','Air-to-Ground Audio','Caution and warning system','Push-to-talk','Communications carrier','Voice-operated switch']::text[],ARRAY['Assuming the cap itself transmits radio, when it only carries microphones and earphones that feed the suit''s separate communications equipment','Overlooking that the dual microphones are for redundancy rather than stereo pickup']::text[],ARRAY['An astronaut dons the Snoopy cap before a spacewalk and runs a communications check','A crew member hears a caution tone through the cap''s earphones','A technician verifies both microphones during pre-flight testing']::text[],'beginner','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Communications Carrier Assembly (CCA, "Snoopy Cap")');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3e7d7dd4-2b62-5aa8-823c-ab095cda3c1b','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3e7d7dd4-2b62-5aa8-823c-ab095cda3c1b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3e7d7dd4-2b62-5aa8-823c-ab095cda3c1b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eb801ff0-bee6-55bc-b013-a21f75e21eec','Air-to-Ground Audio','The voice communication link that carries speech between a crewed aircraft or spacecraft and a ground station or mission-control facility. In spaceflight the air-to-ground loop connects the crew with the capsule communicator at mission control; the voice is typically digitized and relayed over radio links, historically line-of-sight UHF or VHF and, for on-orbit vehicles, S-, Ku-, or Ka-band channels through tracking-and-data-relay satellites. One primary crew loop is kept distinct from the many internal coordination loops so that critical crew traffic is not lost in background chatter.','Air-to-ground audio is the voice link between a flight crew and the ground. Astronauts and pilots use it to talk with controllers below. The voice travels by radio, often through relay satellites. In spaceflight the crew talks to a person called CAPCOM. One main channel is kept just for the crew''s voice.','It gives the flight crew a reliable, prioritized voice path to controllers for commands, status reports, and coordination. Keeping it separate from the many internal loops ensures important crew traffic is not buried under controllers talking among themselves.','It is realized through the vehicle''s radios and the ground''s voice-distribution system. Ground communicators and engineers monitor and speak on assigned loops, and technicians configure, patch, and troubleshoot the air-to-ground channels and their relay-satellite links.','Aviation, Marine, Emergency & Specialized-Transport Audio',ARRAY['CAPCOM','Voice loop','Communications Carrier Assembly','Tracking and Data Relay Satellite','S-band communications','Push-to-talk']::text[],ARRAY['Assuming everyone at mission control talks directly to the crew, when normally only the capsule communicator uses the air-to-ground loop','Confusing the single air-to-ground crew loop with the many internal voice loops that controllers use among themselves']::text[],ARRAY['An astronaut reports a system status to the capsule communicator over the air-to-ground loop','A pilot receives a clearance from a ground controller by radio','A ground technician patches a relay-satellite link to restore air-to-ground voice']::text[],'intermediate','','','5df6f5ec-e98f-4003-a412-a16c0201c661' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Air-to-Ground Audio');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eb801ff0-bee6-55bc-b013-a21f75e21eec','5df6f5ec-e98f-4003-a412-a16c0201c661',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eb801ff0-bee6-55bc-b013-a21f75e21eec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eb801ff0-bee6-55bc-b013-a21f75e21eec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5e80a89e-2d7b-51c0-aabc-97f44b2f4182','Vehicle Sound Package','The coordinated collection of acoustic materials distributed through a vehicle to control interior noise, comprising porous absorbers, limp-mass or elastomeric barriers, constrained- and free-layer damping treatments, and sealing elements. Absorbers dissipate reverberant airborne energy in the cabin, mass-barrier layers provide transmission loss across dash, floor, and wheelhouse boundaries, damping reduces resonant panel vibration, and seals close leakage paths at doors, glazing, and body apertures. Material selection, areal mass, and placement are optimized against weight and cost targets using measured absorption and transmission-loss data together with contribution and transfer-path results.','A sound package is a set of parts that make a car quieter. It uses foam, mats, seals, and heavy liners. Some parts soak up sound inside the cabin. Others block sound or stop panels from buzzing. Engineers pick and place each part to cut noise.','It exists to attenuate structure-borne and airborne noise reaching occupants, targeting both broadband road and wind noise and tonal powertrain content while meeting mass, packaging, thermal, and cost constraints for the whole vehicle.','NVH engineers specify and validate it on dynamometers, in semi-anechoic chambers, and during road testing, iterating layer build-ups on the dash panel, floor, wheelhouses, headliner, and trim using absorption, insertion-loss, and articulation-index measurements.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Acoustic Trim Package','Transmission Loss','Sound Absorption Coefficient','Constrained-Layer Damping','Airborne Road Noise','Panel Contribution Analysis (PCA)']::text[],ARRAY['Treating the package as pure mass and adding weight everywhere instead of matching absorption and barrier layers to each frequency region','Ignoring small air-leak paths at seals and grommets that dominate high-frequency intrusion regardless of barrier mass','Confusing absorption with transmission loss and expecting open-cell foam alone to block noise','UNSAFE: piling on aftermarket deadener that covers airbag seams or seatbelt anchors, or that blocks factory water-drainage holes and invites corrosion']::text[],ARRAY['Tuning dash-panel insulator build-up to reduce engine noise at the driver''s ear','Adding wheelhouse liners and floor barriers to lower coarse-road booming','Diagnosing a wind-noise complaint traced to a failed door seal rather than the barrier layer']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vehicle Sound Package');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5e80a89e-2d7b-51c0-aabc-97f44b2f4182','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5e80a89e-2d7b-51c0-aabc-97f44b2f4182') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5e80a89e-2d7b-51c0-aabc-97f44b2f4182');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4e434e7-d72e-5ced-8b73-3e94142c5b61','Acoustic Trim Package','The set of visible and hidden interior trim components engineered to deliver acoustic functions in addition to their appearance and structural roles, including headliners, carpet systems with decoupler foams, door trim pads, pillar and parcel-shelf trims, and molded dash and floor insulators. Each part is designed for a specified sound-absorption coefficient, transmission loss, vibration damping, or sealing behavior, characterized through impedance-tube and reverberation-room absorption tests and transmission-loss measurement. It overlaps with the broader sound package but emphasizes trim hardware whose acoustic performance is integrated with styling and manufacturing constraints.','Acoustic trim is interior parts that also fight noise. Think of headliners, carpets, and door pads. They soak up sound and help block it. Some also stop metal panels from shaking. Each part is tuned for how the car sounds inside.','It provides distributed absorption and sealing at the surfaces occupants touch and see, converting ordinary cosmetic trim into working acoustic elements so noise control is achieved without dedicated add-on hardware.','Trim and NVH engineers validate headliner, carpet, and door-pad acoustics in impedance tubes and reverberation rooms, then confirm in-vehicle benefit through sound-pressure and articulation-index measurements during development builds.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Vehicle Sound Package','Sound Absorption Coefficient','Transmission Loss','Headliner','Decoupler Foam','Airborne Road Noise']::text[],ARRAY['Assuming decorative trim has no acoustic role and swapping materials for cosmetics without checking absorption or sealing loss','Overlooking the decoupler layer beneath carpet, which sets much of the floor insulation performance','Believing thicker trim always helps, when air gaps and mounting stiffness can degrade transmission loss']::text[],ARRAY['Selecting a headliner substrate to raise mid-frequency cabin absorption','Redesigning a door trim pad to close a leakage path around the speaker grille','Comparing carpet decoupler foams to meet a floor insertion-loss target at fixed mass']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Trim Package');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4e434e7-d72e-5ced-8b73-3e94142c5b61','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4e434e7-d72e-5ced-8b73-3e94142c5b61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4e434e7-d72e-5ced-8b73-3e94142c5b61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '91c12bfd-9a5f-5691-939a-cc869d092cd6','Transfer Path Analysis (TPA)','An experimental and analytical framework that decomposes a measured noise or vibration response at a receiver into the contributions of individual transmission paths connecting active sources to that receiver. The response is modeled as the sum over paths of a path frequency-response function multiplied by an operational load, where classical TPA obtains operational forces by matrix inversion of measured passive-side accelerances (mount-stiffness or matrix-inverse methods) and combines them with separately measured structural or acoustic transfer functions. The result ranks each path and source so dominant contributors can be identified and prioritized for treatment.','Transfer path analysis finds how noise reaches your ears. A car has many sources, like the engine and tires. Their energy travels along set paths to the cabin. This method measures each path''s share of the sound. Then engineers fix the loudest paths first.','It exists to separate source strength from path sensitivity so engineers know whether to quiet a source, stiffen or soften a mount, or treat a body path, turning a vague noise complaint into a ranked list of contributors.','NVH teams apply it on engine mounts, subframe bushings, and exhaust hangers using accelerometers, force estimates, and measured transfer functions to rank paths feeding a target microphone at the driver''s ear.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Operational Transfer Path Analysis (OTPA)','Component-Based Transfer Path Analysis (C-TPA)','Acoustic Transfer Function (ATF)','Panel Contribution Analysis (PCA)','Frequency Response Function','Structure-Borne Road Noise']::text[],ARRAY['Under-instrumenting the interface and missing a real path, so its energy is wrongly assigned to the paths that were measured','Treating estimated operational forces as exact when matrix inversion is ill-conditioned near resonances','Confusing the passive transfer-function measurement with the operational run and mixing their coordinate systems']::text[],ARRAY['Ranking engine-mount paths driving a boom at a fixed engine order','Deciding between a stiffer bushing and added body damping to cut structure-borne road noise','Validating that a countermeasure lowered the dominant path rather than shifting energy elsewhere']::text[],'advanced','p(ω) = Σ_i H_i(ω)·F_i(ω)','The receiver response equals the sum over all transmission paths of each path''s transfer function multiplied by the operational load acting at that path''s interface, evaluated at every frequency.','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer Path Analysis (TPA)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '91c12bfd-9a5f-5691-939a-cc869d092cd6','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='91c12bfd-9a5f-5691-939a-cc869d092cd6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='91c12bfd-9a5f-5691-939a-cc869d092cd6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cbd38fac-6f7a-508d-a944-8300c5bb39eb','Operational Transfer Path Analysis (OTPA)','A transfer-path method that estimates path contributions almost entirely from operational measurements, relating multiple reference signals acquired near the sources to target responses through a transmissibility matrix identified from the operating data itself. Because it does not require dismantling the vehicle to measure force-to-response transfer functions or to invert mount stiffnesses, OTPA is faster than classical TPA, but the identified transmissibilities are sensitive to source coherence, cross-talk between references, and the conditioning of the measured data, typically requiring singular-value decomposition and principal-component techniques to suppress correlated-source errors.','This is a faster kind of transfer path analysis. It works from data taken while the car is driven. It does not need the parts taken apart first. Sensors record signals during real running. Math then splits the noise among the paths.','It exists to shorten test time by skipping separate transfer-function and force measurements, giving quick path rankings from operating data when schedule matters more than the physical rigor of classical TPA.','Engineers deploy dense reference arrays on operating vehicles, then use transmissibility and singular-value methods to attribute road, wind, or powertrain noise to paths without removing components.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Transfer Path Analysis (TPA)','Component-Based Transfer Path Analysis (C-TPA)','Transmissibility','Singular Value Decomposition','Coherence','Structure-Borne Road Noise']::text[],ARRAY['Interpreting transmissibilities as physical forces, when they only relate measured signals and can hide the true source','Ignoring cross-coupling between highly correlated references, which smears contributions across paths','Placing too few reference sensors to resolve closely spaced or coherent sources']::text[],ARRAY['Quickly screening road-noise paths on a proving-ground vehicle without teardown','Attributing wind-noise references to body regions during a chamber test','Comparing two build variants when time forbids full classical TPA']::text[],'advanced','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Operational Transfer Path Analysis (OTPA)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cbd38fac-6f7a-508d-a944-8300c5bb39eb','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cbd38fac-6f7a-508d-a944-8300c5bb39eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cbd38fac-6f7a-508d-a944-8300c5bb39eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0c2e786e-0669-5a7c-952b-aa668976f967','Component-Based Transfer Path Analysis (C-TPA)','A transfer-path approach in which an active component is characterized independently by an invariant set of equivalent interface loads (blocked forces) obtained on a test rig, and this description is then coupled numerically to any passive receiver structure using frequency-based substructuring to predict installed noise and vibration. Because the blocked forces are a property of the source alone, the component can be virtually assembled into different vehicles or subframes to forecast NVH before hardware exists, provided the interface degrees of freedom are adequately measured and the substructuring is well conditioned.','This method tests car parts on their own. Each part gets its own noise fingerprint. A computer then joins the parts virtually. It predicts how they will sound once built in. Engineers can judge a part before the car exists.','It exists to make source descriptions transferable, so a supplier''s component can be assessed in a virtual vehicle early in design and reused across programs without repeating full-vehicle tests.','Engineers measure blocked forces of pumps, compressors, or e-drives on a rig, then couple them by dynamic substructuring to receiver models to predict interior response before prototypes are built.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Transfer Path Analysis (TPA)','Blocked Force','Frequency-Based Substructuring','Operational Transfer Path Analysis (OTPA)','Acoustic Transfer Function (ATF)','Interface Force']::text[],ARRAY['Assuming blocked forces stay invariant when the interface is poorly defined or under-instrumented','Neglecting rotational degrees of freedom at the interface, which corrupts the coupling prediction','Trusting the virtual assembly without validating the substructuring against a measured build']::text[],ARRAY['Predicting e-compressor whine in a vehicle from rig-measured blocked forces','Comparing supplier e-drive units virtually before selecting hardware','Reusing a validated pump source model across two platform variants']::text[],'advanced','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Component-Based Transfer Path Analysis (C-TPA)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0c2e786e-0669-5a7c-952b-aa668976f967','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0c2e786e-0669-5a7c-952b-aa668976f967') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0c2e786e-0669-5a7c-952b-aa668976f967');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7170463-8fb0-5520-b5e0-38e8d4d1a0a0','Panel Contribution Analysis (PCA)','A technique that quantifies how much each vibrating body panel contributes to the sound pressure at a chosen interior location by combining the panel''s operating surface velocity with its acoustic transfer function to that receiver, then summing the complex per-panel contributions. The panel-to-ear acoustic transfer functions are measured reciprocally with a volume-velocity source at the receiver point or computed from a cavity model, and operating velocities come from scanning or arrayed vibration measurements, so panels can be ranked and phase interactions revealed, including cases where one panel partially cancels another.','This method scores how much each panel adds to noise. Panels are the flat metal or glass parts of a car. Each one can shake and push air like a speaker. The method ranks them at one seat spot. The worst panels get treated first.','It exists to pinpoint which interior surfaces radiate the most sound at a target seat and frequency, guiding where to add damping or barrier treatment instead of treating the whole body.','Engineers scan floor, roof, dash, and glass surface velocities and measure reciprocal panel-to-ear transfer functions to rank radiating panels during a booming or road-noise investigation.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Acoustic Transfer Function (ATF)','Transfer Path Analysis (TPA)','Cabin Boom / Booming Noise','Surface Velocity','Reciprocity','Structure-Borne Road Noise']::text[],ARRAY['Summing panel magnitudes without phase, which hides cancellations and over-counts total contribution','Under-sampling a large panel''s surface velocity and missing its dominant mode shape','Assuming the loudest-vibrating panel is the largest radiator when its transfer function to the ear may be weak']::text[],ARRAY['Finding which panel drives a low-frequency boom at a rear seat','Deciding where to add constrained-layer damping for maximum road-noise benefit','Confirming a floor treatment reduced that panel''s radiated contribution']::text[],'advanced','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Panel Contribution Analysis (PCA)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7170463-8fb0-5520-b5e0-38e8d4d1a0a0','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7170463-8fb0-5520-b5e0-38e8d4d1a0a0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7170463-8fb0-5520-b5e0-38e8d4d1a0a0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca2154b8-e285-5f9e-b734-9b7b2feb0a25','Tire Cavity Resonance','The acoustic resonance of the toroidal air column enclosed between the tire inner liner and the wheel rim, whose fundamental circumferential mode occurs where one acoustic wavelength equals the mean cavity circumference, placing it for typical passenger tires in roughly the 200 to 250 Hz region. Contact-patch flattening and rotation break the axisymmetry so the single mode splits into two closely spaced peaks, a fore-aft and a vertical mode, separated by a few hertz. Being lightly damped, the resonance couples strongly to the wheel and spindle and is largely independent of vehicle speed in cavity frequency.','Air is trapped inside every tire. That ring of air can ring like a pipe. It has a natural tone near 200 hertz. Road bumps set this air tone off. The tone can then be heard in the cabin.','It is not designed in but arises from tire geometry, and understanding it lets engineers predict and target a persistent tonal road-noise peak that ordinary broadband treatments do not reach.','Engineers identify it as a sharp order-independent peak near 200 Hz in spindle or interior spectra, then apply sound-absorbing foam rings or acoustic dampers inside the tire to suppress it.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Tire Cavity Noise','Structure-Borne Road Noise','Spindle Force','Cabin Boom / Booming Noise','Mode Splitting','Acoustic Damping']::text[],ARRAY['Confusing the fixed cavity frequency with tread-pattern noise that changes with speed','Expecting exterior trim or absorption to cut a lightly damped, structure-borne cavity tone','UNSAFE: lowering inflation pressure to detune the cavity mode, which degrades handling, load capacity, and heat resistance']::text[],ARRAY['Tracing a steady 210 Hz hum to the tire cavity rather than the powertrain','Evaluating in-tire foam rings to damp the resonance','Explaining twin peaks in a loaded-tire spectrum as fore-aft and vertical modes']::text[],'intermediate','f₀ ≈ c / (2·π·r_m) = c / L_cav','The fundamental tire cavity resonance frequency equals the speed of sound in the enclosed gas divided by the mean circumferential length of the toroidal air cavity, which is two pi times the cavity''s mean radius.','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tire Cavity Resonance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca2154b8-e285-5f9e-b734-9b7b2feb0a25','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca2154b8-e285-5f9e-b734-9b7b2feb0a25') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca2154b8-e285-5f9e-b734-9b7b2feb0a25');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e5f8c400-c917-50b7-ad78-b42e2f6842ad','Tire Cavity Noise','The interior noise that results when the tire acoustic cavity resonance is excited by road roughness and its energy is transmitted structurally through the tire, wheel, spindle, suspension, and body into the cabin, radiating as a tonal peak typically near 200 to 250 Hz. Because the excitation is broadband road input while the cavity is a lightly damped resonator, the response appears as a narrow, order-independent peak, often split into two adjacent tones under load, and it is chiefly a structure-borne phenomenon rather than an airborne one.','This is the cabin sound from the tire air tone. Road bumps excite the air inside the tire. That energy travels up through the wheel and body. You hear it as a hum near 200 hertz. It is worse on rough roads.','Naming the in-cabin symptom separately from the underlying resonance lets engineers target the transmission path and receiver, not just the tire, when reducing this specific tonal road noise.','Engineers confirm it with interior microphones and spindle accelerometers showing a fixed-frequency peak, then treat it with in-tire absorbers, tuned wheel dampers, or suspension-path changes.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Tire Cavity Resonance','Structure-Borne Road Noise','Airborne Road Noise','Cabin Boom / Booming Noise','Spindle Force','Suspension Isolation']::text[],ARRAY['Treating it as airborne and adding absorption when the dominant path is structure-borne through the suspension','Assuming it scales with speed like tread noise, when the cavity frequency is nearly fixed','Blaming wheel bearings or driveline for a tone that is actually the tire cavity mode']::text[],ARRAY['Investigating a coarse-road hum that persists across a range of speeds','Choosing between in-tire foam and a wheel damper to cut the peak','Separating cavity noise from tread pattern noise in a road-noise breakdown']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tire Cavity Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e5f8c400-c917-50b7-ad78-b42e2f6842ad','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e5f8c400-c917-50b7-ad78-b42e2f6842ad') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e5f8c400-c917-50b7-ad78-b42e2f6842ad');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87968849-7661-5e51-ba39-34ad43de6c7e','Cabin Boom / Booming Noise','An objectionable low-frequency interior noise, generally below about 100 Hz, perceived as a pressurizing, throbbing sound and felt as much as heard, produced when a resonant amplifier such as a body acoustic cavity mode or a flexible-panel mode is driven by powertrain orders, road input, or exhaust pulsation. It is characterized by a strong build-up of sound pressure at particular engine speeds or road conditions where the excitation frequency aligns with the resonance, and it is aggravated by lightly damped panels and by acoustic modes of the enclosed cabin air.','Boom is a low, heavy sound inside a car. You feel it press on your ears. It comes when the cabin air resonates. The engine, road, or exhaust can drive it. It often shows up at set engine speeds.','Identifying boom as a resonance problem, not just a loud source, directs the fix toward detuning or damping the cavity or panel mode rather than only quieting the excitation.','Engineers capture it as a sound-pressure peak in engine-speed order tracking or road spectra, then add panel damping, tune the acoustic cavity, or adjust mounts and exhaust to move the resonance.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Structure-Borne Road Noise','Panel Contribution Analysis (PCA)','Acoustic Cavity Mode','Engine Order','Constrained-Layer Damping','Transfer Path Analysis (TPA)']::text[],ARRAY['Chasing the loudest source instead of the resonance that amplifies it at a specific frequency','Adding mass broadly rather than damping the specific panel or detuning the cavity mode','Overlooking exhaust and intake pulsation as the excitation driving a powertrain-order boom']::text[],ARRAY['A pressurizing boom appearing only around a narrow engine-speed band','A coarse-road boom traced to a floor panel resonance','Retuning an exhaust hanger and volume to shift a booming order out of the operating range']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cabin Boom / Booming Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87968849-7661-5e51-ba39-34ad43de6c7e','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87968849-7661-5e51-ba39-34ad43de6c7e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87968849-7661-5e51-ba39-34ad43de6c7e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8e83c2a1-cffc-588e-9b87-9176e5cf711a','Structure-Borne Road Noise','Interior road noise created when tire and road interaction generates vibration that propagates mechanically through the wheel, spindle, suspension links, bushings, and subframe into the body structure, where flexible panels then radiate the energy as sound into the cabin. It dominates the lower-frequency road-noise region, roughly up to a few hundred hertz, is governed by the vibration isolation of mounts and bushings and by the modal behavior and damping of the body, and is analyzed with transfer-path and panel-contribution methods that trace paths from the spindle to the occupant.','This road noise travels through solid parts. Tire shake passes into the suspension and frame. The metal carries it to the cabin panels. Those panels then push air and make sound. It is strongest at low frequencies.','Distinguishing the structural path from the airborne one tells engineers to work on isolation, bushings, and body damping rather than on sealing and absorption to cut low-frequency road noise.','Engineers instrument spindles and body attachments, run TPA from wheel inputs, and tune bushing rates, subframe isolation, and panel damping to reduce the transmitted vibration.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Airborne Road Noise','Transfer Path Analysis (TPA)','Tire Cavity Noise','Suspension Isolation','Panel Contribution Analysis (PCA)','Cabin Boom / Booming Noise']::text[],ARRAY['Adding sound absorption to fix a low-frequency problem that is actually transmitted through the structure','Stiffening a bushing for handling without checking the resulting rise in transmitted road noise','Ignoring subframe and body-attachment isolation while focusing only on the tire']::text[],ARRAY['Reducing a low-frequency road rumble by softening a rear subframe bushing','Using TPA to rank suspension paths feeding the driver''s ear on coarse roads','Adding body damping where a panel radiates transmitted vibration']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Structure-Borne Road Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8e83c2a1-cffc-588e-9b87-9176e5cf711a','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8e83c2a1-cffc-588e-9b87-9176e5cf711a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8e83c2a1-cffc-588e-9b87-9176e5cf711a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9c173e6f-18b1-50be-a655-17b79aad7d72','Airborne Road Noise','Interior road noise carried as acoustic waves radiated by the tire and road contact through the surrounding air, which then enters the cabin by transmission through body panels and glazing and by leakage through seals, grommets, and apertures. It dominates the higher-frequency road-noise region, above a few hundred hertz, is controlled by the transmission loss of panels and glass, by absorption inside wheelhouses and the cabin, and above all by the integrity of sealing, and it is treated separately from the structure-borne component that travels through the suspension.','This road noise travels through the air. Tires on rough roads make a hissing sound. That sound moves through the air to the car. It leaks in through panels, glass, and seals. Better sealing and thicker glass cut it down.','Separating the airborne path directs the fix toward transmission loss, wheelhouse absorption, and sealing rather than toward isolation and bushings that only affect the structural path.','Engineers hunt leaks with ultrasonic sources, measure panel and glass insertion loss, and add wheelhouse liners and barrier layers to cut high-frequency road hiss.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Structure-Borne Road Noise','Transmission Loss','Sound Absorption Coefficient','Sealing','Vehicle Sound Package','Wind Noise']::text[],ARRAY['Overlooking small seal or grommet leaks that dominate high-frequency intrusion regardless of panel mass','Adding open-cell absorption where transmission loss or sealing is what is needed','Attributing high-frequency road hiss to the suspension path instead of airborne transmission']::text[],ARRAY['Finding a wheelhouse absorption deficit driving coarse-road hiss','Locating a body-seal leak with an ultrasonic leak detector','Choosing thicker acoustic laminated glass to raise cabin transmission loss']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Airborne Road Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9c173e6f-18b1-50be-a655-17b79aad7d72','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9c173e6f-18b1-50be-a655-17b79aad7d72') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9c173e6f-18b1-50be-a655-17b79aad7d72');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c70429b3-8a7b-575f-a0a0-2048c35cab26','Pass-By Noise','The exterior noise a vehicle emits, quantified as an A-weighted sound level measured while the vehicle traverses a defined test section past microphones set a fixed lateral distance from the path centerline, under standardized surface, speed, gear, and acceleration conditions. The governing engineering method places microphones at 7.5 m from the centerline and combines constant-speed and full-acceleration runs to represent typical urban driving, yielding a single rating used for type-approval against regulatory limits and as a target that constrains tire, powertrain, exhaust, and intake noise design.','Pass-by noise is how loud a car sounds outside. A car drives past microphones by the road. The test follows strict rules for speed and gear. It shows the noise the car sends to others. Laws set limits a car must meet.','It exists to give a repeatable, regulated measure of the noise a vehicle imposes on its surroundings, enabling type-approval and driving design trade-offs among tire, exhaust, intake, and powertrain sources.','Engineers run acceleration and constant-speed passes on a certified track or in an indoor pass-by facility, then decompose the result with arrays or simulation to find which source drives the rating.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Exterior Noise','A-Weighting','Tire-Road Noise','Exhaust Noise','Sound Power Level','Airborne Road Noise']::text[],ARRAY['Assuming interior quietness predicts pass-by level, when exterior sources and directivity differ','Neglecting tire selection, which often dominates the modern accelerated pass-by result','Ignoring test-surface and temperature controls that materially shift the measured level']::text[],ARRAY['Certifying a new model against regulatory exterior-noise limits','Ranking exhaust versus tire contribution to a failing pass-by level','Reproducing a track result in an indoor pass-by chamber for development']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pass-By Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c70429b3-8a7b-575f-a0a0-2048c35cab26','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c70429b3-8a7b-575f-a0a0-2048c35cab26') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c70429b3-8a7b-575f-a0a0-2048c35cab26');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0217440b-68b7-5627-935e-e58473c9d623','Acoustic Transfer Function (ATF)','A complex, frequency-dependent function that describes the linear relationship between an excitation at a source location and the resulting sound pressure at a receiver location, most commonly expressed as the sound pressure produced per unit source volume velocity or per unit input force. It captures both magnitude and phase of the source-to-receiver acoustic path, is often obtained reciprocally by driving a volume-velocity source at the receiver and measuring at the source surface, and serves as the path sensitivity term that, multiplied by operating source strengths, yields interior response in transfer-path and panel-contribution analyses.','An acoustic transfer function links a source to a sound. It tells how a push at one spot makes sound at another. It changes with frequency. Engineers measure it for each path in a car. It shows which paths carry sound best.','It provides the path-sensitivity building block that separates how strongly a source acts from how efficiently the cabin turns that action into pressure at the occupant, enabling contribution and prediction methods.','Engineers measure it reciprocally with a volume-velocity source at the seat position, building panel-to-ear and mount-to-ear functions used in PCA and TPA to rank and predict interior noise.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Transfer Path Analysis (TPA)','Panel Contribution Analysis (PCA)','Frequency Response Function','Reciprocity','Volume Velocity','Acoustic Cavity Mode']::text[],ARRAY['Ignoring phase and treating the function as a magnitude gain, which breaks contribution summation','Measuring in a nonlinear or leaky condition that violates the assumed reciprocity','Assuming one measurement holds after body changes that alter the cavity or panel behavior']::text[],ARRAY['Building panel-to-ear functions for a booming-noise contribution study','Using reciprocal volume-velocity measurement to get mount-to-ear sensitivities','Combining measured functions with operating forces to predict interior response']::text[],'advanced','p(ω) = H_a(ω)·Q(ω);  H_a(ω) = p(ω) / Q(ω)','Sound pressure at the receiver equals the acoustic transfer function times the source volume velocity; the transfer function is the ratio of received pressure to source strength at each frequency.','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic Transfer Function (ATF)');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0217440b-68b7-5627-935e-e58473c9d623','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0217440b-68b7-5627-935e-e58473c9d623') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0217440b-68b7-5627-935e-e58473c9d623');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '20cf709a-7472-50ec-a506-daa73770b413','Binaural Vehicle Measurement','A binaural vehicle measurement captures interior or exterior vehicle sound with two microphones located at the ear-canal entrances of an artificial head or manikin, reproducing the acoustic filtering imposed by the head, pinnae, and torso. The resulting two-channel signal preserves the interaural level and time differences and the spectral cues that govern human localization and timbre, so headphone playback recreates the spatial and tonal character an occupant would experience. Because the acquisition path mirrors the listener''s own head-related transfer functions, such recordings support perceptually valid sound-quality analysis and jury evaluation rather than single-microphone level metrics alone.','Engineers record car sounds using a fake head with two ear mics. The mics sit where a driver''s ears would be. This captures sound the way people really hear it. The left and right signals keep the true stereo feel. Played back on headphones, the sound feels lifelike. It helps teams judge how noise will bother real people.','It provides a perceptually faithful record of the sound field at the ear, retaining the spatial and binaural cues that conventional free-field or single-microphone measurements discard, so objective metrics and listening juries can assess how vehicle noise is actually experienced.','NVH engineers mount an artificial head in the driver or passenger seat during road, chassis-dynamometer, or track testing, record component and operating conditions binaurally, then replay and post-process the signals for sound-quality metrics, equalization, and A/B jury comparisons.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Artificial head (HATS)','Head-related transfer function','Vehicle sound quality','Interior vehicle noise measurement','Interaural level difference','Psychoacoustic metrics']::text[],ARRAY['Assuming a single free-field microphone captures the same perceptual information as a binaural pair at the ears','Neglecting artificial-head calibration or applying the wrong free-field versus diffuse-field equalization for playback','Comparing binaural recordings against loudspeaker or non-binaural data without accounting for the head-related filtering']::text[],ARRAY['Recording powertrain run-ups in a vehicle to build a jury test of engine sound character','Capturing wind-noise character at highway speed for a driver-seat sound-quality assessment','Documenting an interior buzz or rattle at the occupant''s ear for troubleshooting']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Binaural Vehicle Measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '20cf709a-7472-50ec-a506-daa73770b413','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='20cf709a-7472-50ec-a506-daa73770b413') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='20cf709a-7472-50ec-a506-daa73770b413');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5385545d-a5ef-571c-8fee-8b9f89c277d7','Vehicle Sound Quality','Vehicle sound quality is the discipline that characterizes how vehicle sounds are perceived and judged, combining objective psychoacoustic metrics with subjective evaluation. Beyond A-weighted level it quantifies attributes such as loudness (perceived magnitude), sharpness (high-frequency spectral balance), roughness and fluctuation strength (amplitude-modulation percepts), and tonality (prominence of discrete tones), computed from calibrated, often binaural, signals. These metrics are correlated with jury ratings of annoyance, pleasantness, powerfulness, or brand character, allowing engineers to target a desired sonic signature rather than merely minimizing sound pressure level.','Sound quality is about how a car sound feels, not just how loud it is. Two sounds can be equally loud but feel very different. Engineers rate sounds for loudness, sharpness, roughness, and how tones stand out. These ratings match how people react to the sound. A brand may want an engine to sound strong yet smooth. The goal is a sound people find pleasant or fitting.','It exists to connect measurable signal properties to human judgment, so noise and sound can be engineered for acceptability, comfort, and brand identity instead of being reduced to a single loudness number that ignores perceived character.','Engineers compute psychoacoustic metrics from binaural recordings, correlate them with jury or customer-clinic scores, and use the results to set targets and evaluate design changes for engine, exhaust, wind, road, and electric-drive sounds.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Loudness (psychoacoustics)','Sharpness','Roughness','Fluctuation strength','Tonality','Binaural vehicle measurement']::text[],ARRAY['Treating A-weighted sound pressure level as a complete measure of perceived quality','Optimizing a single metric such as loudness while ignoring sharpness, tonality, or modulation percepts','Assuming quieter is always better, when occupants may expect a characteristic or reassuring sound']::text[],ARRAY['Tuning exhaust or intake sound toward a sporty yet non-fatiguing character','Diagnosing why a tonal electric-drive whine is rated annoying despite a low overall level','Setting sound-quality targets from customer-clinic jury data for a new model']::text[],'advanced','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vehicle Sound Quality');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5385545d-a5ef-571c-8fee-8b9f89c277d7','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5385545d-a5ef-571c-8fee-8b9f89c277d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5385545d-a5ef-571c-8fee-8b9f89c277d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '15f89831-34e4-5de3-a0d4-a10523c88205','Interior Vehicle Noise Measurement','Interior vehicle noise measurement is the standardized acquisition of sound pressure inside a vehicle cabin under defined operating and environmental conditions. Microphones are placed at specified occupant positions, typically near the ears at the driver and passenger seats, while the vehicle is run at prescribed steady speeds, during acceleration, or under stationary engine conditions. The procedure fixes microphone locations, road or dynamometer conditions, and signal processing so that measured levels and spectra are reproducible and comparable between vehicles, supporting both documentation and engineering diagnosis of interior noise.','This means measuring the noise inside a car in a set way. Mics are placed at seats, near where ears would be. The car is driven at fixed speeds or run in place. Rules say where mics go and how to run the test. This lets teams compare cars fairly and track noise. Standard steps make sure results can be repeated.','It provides repeatable, comparable data on cabin sound levels and spectral content, giving engineers a controlled baseline to benchmark vehicles, verify targets, and localize dominant noise sources and paths.','Technicians run coast-downs, steady-speed passes, and wide-open-throttle accelerations on road or chassis dynamometer with seat-position microphones, then analyze level, spectra, and order content to characterize and troubleshoot interior noise.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Sound pressure level','A-weighting','Binaural vehicle measurement','Order analysis','Chassis dynamometer','Occupant ear position']::text[],ARRAY['Placing microphones inconsistently so results cannot be compared across runs or vehicles','Ignoring background and wind conditions that contaminate low-level measurements','Reporting only overall level without the spectral or order content needed to find the source']::text[],ARRAY['Measuring steady 100 km/h cabin noise to benchmark against a competitor','Documenting wide-open-throttle interior level for a powertrain refinement target','Verifying an interior noise target after adding acoustic sealing or absorption']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interior Vehicle Noise Measurement');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '15f89831-34e4-5de3-a0d4-a10523c88205','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='15f89831-34e4-5de3-a0d4-a10523c88205') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='15f89831-34e4-5de3-a0d4-a10523c88205');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97fc20c6-d36a-5d8d-a7f6-7c939c423848','Tire-Road Noise','Tire-road noise is the airborne and structure-borne sound generated by the dynamic interaction between a rolling tire and the road surface. Airborne mechanisms include tread-block impacts, air pumping as tread cavities compress and release, and horn-effect amplification at the tire-road wedge, while structure-borne energy from tire-belt and sidewall vibration transmits through the spindle and suspension into the cabin. Its spectrum depends on tread pattern, tire construction, road texture, speed, and load, and it typically dominates interior noise at cruising speeds where powertrain and wind contributions are lower.','This is the sound made when tires roll over a road. The tread blocks hit the road and trap and release air. The tire body also shakes as it rolls. Rougher roads and faster speeds make this noise louder. It is a big part of cabin noise at highway speed. It stays even when the engine is quiet or off.','Understanding it lets engineers isolate and control a dominant cruising-speed noise source, guiding tire, suspension-isolation, and body-sealing design to reduce both the airborne and structure-borne paths into the cabin.','NVH teams measure it with coast-down tests, drum rigs, and on-road runs, use transfer-path analysis to separate airborne from structure-borne paths, and evaluate tire and bushing changes for cabin noise reduction.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Rolling noise','Transfer path analysis','Road texture','Structure-borne noise','Tread pattern pitch','Horn effect']::text[],ARRAY['Assuming all tire-road noise is airborne and ignoring the structure-borne path through the suspension','Judging tires only by tread-noise pitch while overlooking broadband road-texture excitation','Attributing cruising-speed cabin noise to wind or powertrain when the tires actually dominate']::text[],ARRAY['Diagnosing a highway-speed cabin drone traced to structure-borne tire vibration','Comparing tire models on a coarse chip-seal surface for road-noise refinement','Tuning subframe bushings to cut a road-noise resonance in the cabin']::text[],'intermediate','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tire-Road Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97fc20c6-d36a-5d8d-a7f6-7c939c423848','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97fc20c6-d36a-5d8d-a7f6-7c939c423848') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97fc20c6-d36a-5d8d-a7f6-7c939c423848');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd4a5146e-f01f-53d1-9dfd-c39dbc76d2ca','Electric Drive Whine','Electric drive whine is tonal, order-related noise radiated by the electric traction system of a vehicle, spanning the motor, the power electronics (inverter), and the reduction gearing. Contributions include electromagnetic radial-force and torque-ripple excitation in the motor at orders set by pole and slot counts, high-frequency tones from inverter pulse-width-modulation switching and its sidebands, and gear-mesh tones from the reduction gears. Because these components produce discrete tones that climb in frequency with speed against a low broadband background, the whine is perceptually prominent and a primary refinement concern in electrified vehicles.','Electric cars can make a high tonal whine. It comes from the motor, the power box, and the gears. These parts make sound tied to how fast they spin. The whine can rise in pitch as the car speeds up. Electric cars are quiet, so this whine is easy to notice. Teams work to lower it or shape it to sound better.','Naming and decomposing this composite tonal noise lets engineers attribute each tone to its motor, inverter, or gear source and target countermeasures, since electric powertrains lack the broadband masking that combustion engines provide.','Engineers use order tracking and run-up spectrograms to separate electromagnetic, switching, and gear-mesh orders, then apply pole and slot design, PWM strategy, gear micro-geometry, and isolation to reduce the offending tones.','Automotive & Vehicle Acoustics (NVH)',ARRAY['E-motor whine','Gear whine','Inverter switching noise','Order analysis','Torque ripple','Reduction gear']::text[],ARRAY['Treating the whine as a single source instead of separating motor, inverter, and gear orders','Overlooking PWM switching tones and their sidebands as a distinct high-frequency contributor','Assuming a quiet overall level means the tonal whine will not be perceived as annoying']::text[],ARRAY['Tracing a rising tone during acceleration to a specific electromagnetic or gear order','Reducing an audible inverter switching tone by adjusting the modulation scheme','Balancing tonal electric-drive character against customer expectations of quiet refinement']::text[],'advanced','','','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electric Drive Whine');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd4a5146e-f01f-53d1-9dfd-c39dbc76d2ca','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d4a5146e-f01f-53d1-9dfd-c39dbc76d2ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d4a5146e-f01f-53d1-9dfd-c39dbc76d2ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd91196bf-35ca-52c2-af53-1123b19a8700','E-Motor Whine','E-motor whine is the tonal noise produced specifically by an electric machine, arising chiefly from electromagnetic radial forces and torque ripple acting on the stator and rotor. Interactions between the permanent-magnet or wound-field flux, the armature currents, and stator-slot permeance create force harmonics whose spatial and temporal orders are governed by the pole-pair and slot counts; low spatial-order forces most effectively excite stator ovalizing modes and radiate sound. The dominant tones occur at electrical-frequency-related orders that scale with rotational speed, so the whine sweeps in pitch during run-up and becomes severe near structural resonances.','This is the whine that comes just from the electric motor. Magnetic forces pull on the motor parts as it spins. These pulls make the metal vibrate and give off tones. The pitch is set by the motor''s poles and its speed. The tone climbs as the motor spins faster. It is a main source of noise in electric cars.','Isolating the motor''s own electromagnetic and mechanical tones lets engineers address the machine as a distinct source, through pole and slot selection, skewing, and stator mounting, separate from inverter and gear contributions.','Engineers identify the characteristic electromagnetic orders in run-up order maps, check them against measured stator modal frequencies, and apply rotor skew, slot and pole optimization, or stator isolation to suppress resonant amplification.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Electromagnetic force order','Torque ripple','Stator mode shape','Cogging torque','Order analysis','Electric drive whine']::text[],ARRAY['Confusing electromagnetic tonal orders with mechanical bearing or gear tones','Ignoring the coincidence of force orders with stator structural modes that amplifies radiation','Assuming skewing or slot changes remove whine without checking the shifted resonance behavior']::text[],ARRAY['Matching a dominant order in a motor run-up to a stator ovalizing mode','Evaluating rotor skew to reduce a prominent electromagnetic whine order','Separating pure motor tones from reduction-gear tones on a test bench']::text[],'advanced','f_e = p · n / 60','The fundamental electrical excitation frequency in hertz equals the number of magnetic pole pairs times shaft speed in revolutions per minute divided by sixty, and dominant whine tones appear at low even multiples of this order.','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='E-Motor Whine');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd91196bf-35ca-52c2-af53-1123b19a8700','d880b947-0203-4f04-916c-49045fe3c09d',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d91196bf-35ca-52c2-af53-1123b19a8700') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d91196bf-35ca-52c2-af53-1123b19a8700');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13f76ca5-f2c0-51ff-972f-2eff9353d0ab','Gear Whine','Gear whine is tonal noise generated by the meshing of loaded gear teeth, driven primarily by transmission error, the deviation between the actual and ideal angular position of the output relative to the input. Tooth deflection under load, manufacturing deviations, and profile geometry cause a periodic fluctuation in mesh stiffness and contact, exciting vibration at the gear-mesh frequency and its harmonics. This vibration transmits through shafts, bearings, and housing to radiate as a speed-dependent tone; its pitch equals the number of teeth times the shaft rotational speed, so it rises with rpm and is often shaped by driveline resonances.','Gear whine is a tone made by gears as their teeth mesh. Teeth are never made perfectly, so they push with small errors. This tiny error repeats each time a tooth meets another. That steady beat turns into a clear tone. The pitch depends on tooth count and how fast the gears spin. Load changes and worn teeth can make it worse.','Identifying gear whine and its transmission-error root cause lets engineers reduce a discrete, annoying tone through tooth micro-geometry, load-tuned profile modifications, and housing or isolation changes.','Engineers measure transmission error and gear-mesh orders on rigs and in vehicle, then apply profile and lead modifications, higher gear quality, and structural changes to reduce whine across the operating load and speed range.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Gear-mesh frequency','Transmission error','Profile modification','Tooth contact pattern','Order analysis','Driveline resonance']::text[],ARRAY['Confusing gear whine with broadband gear rattle, which comes from unloaded teeth impacting','Optimizing tooth micro-geometry at one load and ignoring whine at other torque levels','Blaming bearings for a tone that is actually a gear-mesh order']::text[],ARRAY['Reducing a reduction-gear whine order in an electric axle through profile modification','Tuning helix and profile to minimize transmission error at cruising torque','Separating a gear-mesh order from motor orders in an electric-drive spectrogram']::text[],'intermediate','f_m = z · n / 60','The gear-mesh frequency in hertz equals the number of teeth on a gear times that gear''s rotational speed in revolutions per minute divided by sixty.','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gear Whine');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13f76ca5-f2c0-51ff-972f-2eff9353d0ab','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13f76ca5-f2c0-51ff-972f-2eff9353d0ab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13f76ca5-f2c0-51ff-972f-2eff9353d0ab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24f44d6c-836a-5dc9-ac4d-90925cef0cc8','HVAC Tonal Noise','HVAC tonal noise is discrete-frequency sound produced by a vehicle''s heating, ventilation, and air-conditioning system, most commonly the blower. The dominant tone is the blade-passing frequency, the rate at which fan blades sweep past a fixed point, together with its harmonics, generated by periodic pressure pulses and by interaction of the rotating blades with stationary struts, the volute cutoff, and duct features. Additional tones can arise from compressor orders and from flow-induced whistles at vents and restrictions. Because these tones stand out against the broadband rush of airflow, they are a key cabin sound-quality concern, especially at high fan settings.','This is a clear tone from the car''s heater and cooling fan. The fan blades chop the air as they spin. Each blade passing sends out a puff of pressure. Many puffs per second blend into a steady tone. More blades or higher fan speed raise the pitch. Ducts and vents can make the tone stronger.','Distinguishing tonal HVAC content from broadband airflow noise lets engineers target the periodic blade-passing and flow-interaction mechanisms that make the system sound whiny or annoying rather than simply loud.','Engineers measure blower spectra at each speed setting, identify blade-passing and harmonic tones, and reduce them through blade count and spacing, cutoff clearance, duct redesign, and vent geometry.','Automotive & Vehicle Acoustics (NVH)',ARRAY['Blade-passing frequency','Blower motor','Flow-induced noise','Volute cutoff','Tonality','Compressor order']::text[],ARRAY['Confusing tonal blade-passing noise with the broadband whoosh of ducted airflow','Increasing fan speed to move air while overlooking the rise in blade-passing tone','Ignoring vent and duct geometry as a source of flow-induced whistles']::text[],ARRAY['Reducing a blower blade-passing tone at the highest fan setting','Diagnosing a vent whistle traced to a partially closed register','Applying uneven blade spacing to spread a tonal peak into broadband noise']::text[],'intermediate','f_BPF = B · n / 60','The blade-passing frequency in hertz equals the number of blades on the impeller times its rotational speed in revolutions per minute divided by sixty.','d880b947-0203-4f04-916c-49045fe3c09d' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='HVAC Tonal Noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24f44d6c-836a-5dc9-ac4d-90925cef0cc8','d880b947-0203-4f04-916c-49045fe3c09d',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24f44d6c-836a-5dc9-ac4d-90925cef0cc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24f44d6c-836a-5dc9-ac4d-90925cef0cc8');
